/* `sb` is captured once, here, and used directly by hundreds of call sites. If the SDK
   was not available at this moment (a failed or still-loading vendor script) it would
   stay null forever and every one of those calls would silently no-op — booking and
   payment included. Rebind it if the SDK turns up later. Normal loads bind first time
   and never enter the retry. */
function guidcyBindSupabaseClient(){
  if(sb && typeof sb.from === 'function') return true;
  try{
    if(window.sb && typeof window.sb.from === 'function'){ sb = window.sb; return true; }
    if(window.supabase && window.supabase.createClient && CFG.supabase_url && CFG.supabase_key){
      sb = window.supabase.createClient(CFG.supabase_url, CFG.supabase_key);
      window.sb = sb;
      return true;
    }
  }catch(e){ console.warn('Supabase rebind failed', e); }
  return false;
}
window.guidcyBindSupabaseClient = guidcyBindSupabaseClient;
if(!sb || typeof sb.from !== 'function'){
  var guidcySbTries = 0;
  var guidcySbTimer = setInterval(function(){
    guidcySbTries++;
    if(guidcyBindSupabaseClient() || guidcySbTries >= 40) clearInterval(guidcySbTimer);
  }, 250);
  document.addEventListener('DOMContentLoaded', guidcyBindSupabaseClient);
  window.addEventListener('load', guidcyBindSupabaseClient);
}

/* ─── CENTRALIZED SUPABASE CLIENT — single source of truth, replaces ~40 duplicate
   per-module client()/sbc()/sbClient()/getClient() closures that each re-implemented
   the same window.sb -> window.supabaseClient -> window.__guidcySupabaseClient ->
   lazy-create fallback chain. Every module keeps calling its own local getter name
   (client/sbc/sbClient/getClient/webinarClient); each now just delegates here. ─── */
window.guidcyGetSupabaseClient = function(){
  try{
    if(window.sb && window.sb.from) return window.sb;
    if(window.supabaseClient && window.supabaseClient.from) return window.supabaseClient;
    if(window.__guidcySupabaseClient && window.__guidcySupabaseClient.from) return window.__guidcySupabaseClient;
    if(typeof sb !== 'undefined' && sb && sb.from) return sb;
    var conf = window.CFG || {};
    var url = conf.supabase_url || window.SUPABASE_URL;
    var key = conf.supabase_key || window.SUPABASE_ANON_KEY;
    if(window.supabase && window.supabase.createClient && url && key){
      var created = window.supabase.createClient(url, key);
      window.__guidcySupabaseClient = created;
      if(!window.sb) window.sb = created;
      return created;
    }
  }catch(_){}
  return null;
};

/* Returning to a tab fires focus, pageshow and visibilitychange together, and
   several modules each re-render on all three — so one tab switch caused a burst
   of full innerHTML rewrites that read as flicker. Collapse them to one refresh
   per module per switch; the refresh still happens, just once. */
window.__guidcyVisRefreshOK=function(k){var n=Date.now(),m=window.__guidcyVisRefreshAt||{};if(m[k]&&n-m[k]<1500)return false;m[k]=n;window.__guidcyVisRefreshAt=m;return true};

/* ─── FEE MODEL — single source of truth for every rupee shown or stored ───
   The client pays the consultant's session fee plus a 5% platform fee.
   Guidcy separately takes a 15% commission out of the consultant's fee, so the
   consultant is paid 85% of their own fee. Guidcy therefore earns 20% of the fee
   in total (5% from the client + 15% from the consultant).

   Everything is kept to two decimals rather than whole rupees: on a ₹1 session a
   rupee-rounded 5% collapses to ₹0, which both hid the fee in the UI and meant no
   commission was recorded. Razorpay is charged from `total` in paise. ─── */
window.GUIDCY_PLATFORM_FEE_RATE = 0.05;   // paid by the client, on top of the fee
window.GUIDCY_COMMISSION_RATE   = 0.15;   // deducted from the consultant's fee
window.guidcyRound2 = function(n){
  var x = Number(n || 0);
  if(!Number.isFinite(x) || x <= 0) return 0;
  return Math.round(x * 100) / 100;
};
window.guidcyFees = function(sessionFee){
  var fee = window.guidcyRound2(sessionFee);
  if(fee <= 0) return {fee:0, platformFee:0, total:0, commission:0, payout:0};
  var platformFee = window.guidcyRound2(fee * window.GUIDCY_PLATFORM_FEE_RATE);
  var commission  = window.guidcyRound2(fee * window.GUIDCY_COMMISSION_RATE);
  return {
    fee: fee,
    platformFee: platformFee,
    total: window.guidcyRound2(fee + platformFee),   // what the client pays
    commission: commission,
    payout: window.guidcyRound2(fee - commission)    // what the consultant receives
  };
};
/* ₹1,050 → "₹1,050"; ₹1.05 → "₹1.05". Only a true zero reads as Free. */
window.guidcyMoney = function(v){
  var x = Number(v || 0);
  if(!Number.isFinite(x) || x <= 0) return 'Free';
  var whole = Math.abs(x - Math.round(x)) < 0.005;
  return '₹' + (whole ? Math.round(x).toLocaleString('en-IN')
                      : x.toLocaleString('en-IN',{minimumFractionDigits:2, maximumFractionDigits:2}));
};

/* ─── LAZY SCRIPT LOADER — injects a script tag (src=) on first use only, memoized ─── */
window.__guidcyScriptLoaders = window.__guidcyScriptLoaders || {};
window.guidcyLoadScript = function(src){
  var cache = window.__guidcyScriptLoaders;
  if(cache[src]) return cache[src];
  cache[src] = new Promise(function(resolve, reject){
    var existing = document.querySelector('script[src="'+src+'"]');
    if(existing){ resolve(); return; }
    var el = document.createElement('script');
    el.src = src;
    el.async = true;
    el.onload = function(){ resolve(); };
    el.onerror = function(){ delete cache[src]; reject(new Error('Failed to load script: '+src)); };
    document.head.appendChild(el);
  });
  return cache[src];
};

/* ─── DEBOUNCE — shared helper for search/filter inputs ─── */
window.guidcyDebounce = function(fn, delay){
  var t = null;
  return function(){
    var args = arguments, ctx = this;
    clearTimeout(t);
    t = setTimeout(function(){ fn.apply(ctx, args); }, delay || 200);
  };
};

/* ─── DUPLICATE-SUBMIT GUARD — wraps an async handler so a second click/call
   while the first is still in flight (or within `cooldownMs` after it settles)
   is ignored instead of firing a second request. Used for booking/payment/
   dispute-style mutating actions where a double-click must not create two rows. ─── */
window.guidcyGuardSubmit = function(key, fn, cooldownMs){
  window.__guidcySubmitGuards = window.__guidcySubmitGuards || {};
  var guards = window.__guidcySubmitGuards;
  return async function(){
    if(guards[key]) return;
    guards[key] = true;
    try{
      return await fn.apply(this, arguments);
    }finally{
      setTimeout(function(){ guards[key] = false; }, cooldownMs || 800);
    }
  };
};

/* ─── SUPABASE WRITE — awaits a PostgREST query builder and returns the error,
   or null on success.

   A query builder from @supabase/supabase-js is a *thenable*, not a Promise: it
   implements `then`, but it has no `catch`. So the `.catch(()=>{})` several call
   sites appended to a write threw "….catch is not a function" synchronously,
   BEFORE the request was ever sent — the row was never updated, no request went
   out, and because the throw happened inside an async function nobody awaited,
   the button simply appeared to do nothing. Await it here instead, and let the
   caller decide what to tell the user. ─── */
window.guidcySupabaseWrite = async function(builder){
  try{
    const result = await builder;
    if(result && result.error) return result.error;
    return null;
  }catch(e){ return e || new Error('Request failed'); }
};

/* ─── DASHBOARD LOAD FAILURE — replaces a dashboard panel with a short "could not
   load" card and a Retry button.

   A failed Supabase read used to fall through to `data||[]`, so every dashboard
   rendered its empty state instead: "No users yet", "No upcoming paid sessions",
   "0 Total". There was no way to tell a genuinely empty table apart from a
   permissions or connectivity failure — and on the user dashboard that means
   being told you have no session today when the request simply failed. Paint the
   failure instead. `name` is 'swUD' | 'swCD' | 'swAD'. ─── */
window.guidcyDashLoadFailed = function(name, main, title, tab, error){
  if(!main) return false;
  var message = String((error && (error.message || error.hint)) || 'The data request did not come back.');
  var esc = function(v){ return String(v==null?'':v).replace(/[&<>"']/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c] }) };
  console.warn('Dashboard section "'+tab+'" could not load:', error);
  main.innerHTML = '<div class="dash-title">'+esc(title)+'</div>'+
    '<div class="guidcy-dash-load-error" role="alert">'+
    '<div class="guidcy-dash-load-error-title">Could not load this section</div>'+
    '<p>'+esc(message)+' Nothing has been changed — check your connection and try again.</p>'+
    '<button type="button" class="btn btn-blue" onclick="window.guidcyRetryDashboardSection&&window.guidcyRetryDashboardSection(\''+String(name).replace(/[^a-zA-Z]/g,'')+'\',\''+esc(tab).replace(/[^a-z0-9-]/gi,'')+'\')">Retry</button>'+
    '</div>';
  return true;
};

/* ─── AUTH-READY SIGNAL — fires once initAuth() has resolved the definitive
   logged-in/out state (session restored, or confirmed no session), as opposed
   to the fixed-delay retry polling the router previously relied on alone.
   Fixes: refreshing on a route that depends on auth (e.g. a dashboard) could
   render before the session finished restoring, and nothing re-rendered once
   it did. guidcyOnAuthReady(fn) fires fn once, immediately if auth is already
   resolved, otherwise as soon as initAuth() finishes. ─── */
window.__guidcyAuthReadyCallbacks = [];
window.__guidcyAuthReadyFired = false;
window.guidcyOnAuthReady = function(fn){
  if(window.__guidcyAuthReadyFired){ try{fn()}catch(e){console.warn('guidcyOnAuthReady callback failed',e)} return; }
  window.__guidcyAuthReadyCallbacks.push(fn);
};
window.__guidcyFireAuthReady = function(){
  if(window.__guidcyAuthReadyFired)return;
  window.__guidcyAuthReadyFired = true;
  var cbs = window.__guidcyAuthReadyCallbacks.splice(0);
  cbs.forEach(function(fn){ try{fn()}catch(e){console.warn('guidcyOnAuthReady callback failed',e)} });
};

