/* ═══════════════════════════════════════════
   HELPERS
═══════════════════════════════════════════ */
// ── Mobile menu toggles ──
/* ════════════════════════════════════════════════════════════════
   GUIDCY MOBILE DRAWERS — single source of truth
   Covers the public nav drawer (#gmob-drawer) and the three
   dashboard sidebar drawers (User/Consultant/Admin -> .dash-side).
   This replaces many overlapping patches that had accumulated for
   the same job over time (several competing open/close
   implementations, duplicated scroll-lock logic, and a tap-vs-scroll
   guard that only covered the public drawer). One controller per
   drawer type now owns its open/close/scroll-lock/tap-vs-scroll
   behaviour; nothing else in the file redefines these.
   ════════════════════════════════════════════════════════════════ */
(function(){
  if(window.__guidcyDrawersV2)return;
  window.__guidcyDrawersV2=true;

  /* ── Generic tap-vs-scroll gesture guard ──────────────────────────
     Given a container selector and a tappable-item selector, decide
     on touchend whether a touch that started inside the container was
     a genuine tap (small movement, quick, not right after a scroll)
     or part of a scroll gesture. A real tap fires the item's own
     click ourselves; anything else fires nothing. Either way the
     browser's own (unreliable) click synthesis is cancelled, so it
     never fires late and lands on whatever item the finger happened
     to drift over mid-scroll. touchstart/touchmove are left
     completely untouched (passive, no preventDefault) so native
     scrolling and its momentum are unaffected on both iOS and
     Android - a vertical swipe always scrolls, even starting on an
     item, and normal taps are unchanged. */
  function installTapVsScrollGuard(containerSel,itemSel){
    var MOVE_THRESHOLD=6;
    var MAX_TAP_MS=550;
    var ARM_MS=650;
    var RECENT_TOUCH_MS=1200;

    var gesture=null;
    var armedItem=null;
    var armedUntil=0;
    var lastTouchLikeAt=0;

    function containerFor(target){
      return target&&target.closest?target.closest(containerSel):null;
    }
    function itemFor(target){
      var container=containerFor(target);
      if(!container)return null;
      var item=target&&target.closest?target.closest(itemSel):null;
      return item&&container.contains(item)?item:null;
    }
    function scrollSurface(container){
      if(!container)return null;
      return container.querySelector('.gmob-body')||container;
    }
    function disarm(){
      armedItem=null;
      armedUntil=0;
    }
    function begin(target,x,y,pointerId){
      var container=containerFor(target);
      if(!container)return;
      var surface=scrollSurface(container);
      gesture={
        container:container,
        surface:surface,
        item:itemFor(target),
        startX:x,
        startY:y,
        startScrollTop:surface?surface.scrollTop:0,
        startedAt:Date.now(),
        moved:false,
        scrolled:false,
        pointerId:pointerId
      };
      lastTouchLikeAt=Date.now();
      disarm();
    }
    function move(x,y){
      if(!gesture)return;
      if(Math.abs(x-gesture.startX)>MOVE_THRESHOLD||Math.abs(y-gesture.startY)>MOVE_THRESHOLD){
        gesture.moved=true;
        disarm();
      }
    }
    function end(target,x,y){
      if(!gesture){disarm();return;}
      lastTouchLikeAt=Date.now();
      move(x,y);
      var g=gesture;
      var currentScroll=g.surface?g.surface.scrollTop:0;
      var sameItem=g.item&&itemFor(target)===g.item;
      var quick=(Date.now()-g.startedAt)<=MAX_TAP_MS;
      var stationary=Math.abs(currentScroll-g.startScrollTop)<=1;

      if(!g.moved&&!g.scrolled&&quick&&stationary&&sameItem){
        armedItem=g.item;
        armedUntil=Date.now()+ARM_MS;
      }else{
        disarm();
      }
      gesture=null;
    }
    function cancel(){
      lastTouchLikeAt=Date.now();
      gesture=null;
      disarm();
    }

    /* Pointer Events are the most reliable signal on current iOS/Android.
       A real scroll normally produces pointermove and often pointercancel,
       which means the menu item never gets armed for navigation. */
    if(window.PointerEvent){
      document.addEventListener('pointerdown',function(e){
        if(e.pointerType!=='touch'&&e.pointerType!=='pen')return;
        if(!containerFor(e.target))return;
        begin(e.target,e.clientX,e.clientY,e.pointerId);
      },{passive:true,capture:true});

      document.addEventListener('pointermove',function(e){
        if(!gesture||gesture.pointerId!==e.pointerId)return;
        move(e.clientX,e.clientY);
      },{passive:true,capture:true});

      document.addEventListener('pointerup',function(e){
        if(!gesture||gesture.pointerId!==e.pointerId)return;
        end(e.target,e.clientX,e.clientY);
      },{passive:true,capture:true});

      document.addEventListener('pointercancel',function(e){
        if(!gesture||gesture.pointerId!==e.pointerId)return;
        cancel();
      },{passive:true,capture:true});
    }else{
      /* Fallback for older WebKit. */
      document.addEventListener('touchstart',function(e){
        var t=e.touches&&e.touches[0];
        if(!t||!containerFor(e.target))return;
        begin(e.target,t.clientX,t.clientY,'touch');
      },{passive:true,capture:true});

      document.addEventListener('touchmove',function(e){
        if(!gesture)return;
        var t=e.touches&&e.touches[0];
        if(t)move(t.clientX,t.clientY);
      },{passive:true,capture:true});

      document.addEventListener('touchend',function(e){
        if(!gesture)return;
        var t=e.changedTouches&&e.changedTouches[0];
        if(!t){cancel();return;}
        end(e.target,t.clientX,t.clientY);
      },{passive:true,capture:true});

      document.addEventListener('touchcancel',cancel,{passive:true,capture:true});
    }

    /* Any actual movement of the drawer's scroll surface invalidates the
       pending tap, including inertial/momentum scrolling after finger-up. */
    /* Capture-phase so it also sees scrolls inside the drawer, passive so the
       browser never has to wait on it before scrolling, and it exits on a plain
       boolean before touching the DOM — this runs for every scroll event on the
       page, including ordinary page scrolling that has nothing to do with the
       drawer. */
    document.addEventListener('scroll',function(e){
      if(!armedItem&&!gesture)return;
      var container=containerFor(e.target);
      if(!container&&e.target&&e.target.closest)container=e.target.closest(containerSel);
      if(!container)return;
      lastTouchLikeAt=Date.now();
      if(gesture)gesture.scrolled=true;
      disarm();
    },{capture:true,passive:true});

    /* Safety model: after a touch-like interaction, a drawer item click is
       DENIED unless that exact item was explicitly armed by a short,
       stationary pointer/touch sequence. This prevents the trailing Safari
       click seen in the supplied recording from opening Categories (or any
       other row) after a swipe. Mouse/keyboard clicks remain unchanged. */
    document.addEventListener('click',function(e){
      var container=containerFor(e.target);
      if(!container)return;

      var item=itemFor(e.target);
      if(!item)return; /* e.g. empty drawer area */

      var isClose=item.classList&&item.classList.contains('gmob-close-btn');
      if(isClose)return;

      var recentTouch=(Date.now()-lastTouchLikeAt)<=RECENT_TOUCH_MS;
      if(!recentTouch)return; /* desktop mouse / keyboard activation */

      var allowed=(armedItem===item&&Date.now()<=armedUntil);
      disarm();
      if(!allowed){
        e.preventDefault();
        e.stopPropagation();
        if(e.stopImmediatePropagation)e.stopImmediatePropagation();
      }
    },true);
  }

  /* ════════════ PUBLIC NAV DRAWER ════════════ */
  (function(){
    function $(id){return document.getElementById(id)}
    var drawer=$('gmob-drawer'), overlay=$('gmob-overlay');
    if(!drawer||!overlay)return;
    function blockBackgroundTouch(e){
      if(!(e.target&&e.target.closest&&e.target.closest('#gmob-drawer')))e.preventDefault();
    }

    function ensureOneWebinarButton(){
      var items=Array.prototype.filter.call(drawer.querySelectorAll('button,a'),function(el){return /webinars?/i.test(el.textContent||'')});
      items.forEach(function(el,i){if(i>0)el.remove()});
      if(!items.length){
        var body=drawer.querySelector('.gmob-body')||drawer;
        var btn=document.createElement('button');btn.type='button';btn.className='gmob-item';
        btn.innerHTML='<div class="gmob-icon">🎓</div><span class="gmob-label">Webinars</span><span class="gmob-arrow">›</span>';
        btn.onclick=function(e){e.preventDefault();closeDrawer();setTimeout(function(){window.go&&window.go('webinar')},60)};
        body.appendChild(btn);
      }
    }

    function openDrawer(){
      /* The public drawer and a dashboard drawer are mutually exclusive. */
      try{
        if(typeof window.guidcyCloseDashboardMenu==='function')window.guidcyCloseDashboardMenu();
        else if(typeof window.closeDashMenu==='function')window.closeDashMenu();
      }catch(_){ }
      overlay.classList.add('open');
      drawer.classList.add('open');
      document.body.classList.add('gmob-open','menu-open');
      document.addEventListener('touchmove',blockBackgroundTouch,{passive:false});
      ensureOneWebinarButton();
    }
    function closeDrawer(){
      overlay.classList.remove('open');
      drawer.classList.remove('open');
      document.body.classList.remove('gmob-open','menu-open');
      document.removeEventListener('touchmove',blockBackgroundTouch,false);
      var b=$('mobile-burger'); if(b)b.classList.remove('on');
    }

    window.openMobDrawer=openDrawer;
    window.closeMobDrawer=closeDrawer;
    window.toggleMobileMenu=function(){ drawer.classList.contains('open')?closeDrawer():openDrawer(); };
    window.closeMobileMenu=closeDrawer;

    /* Do not close the menu from an overlay tap/drag. The drawer stays open
       until the user deliberately chooses a menu option or presses the explicit X. */
    overlay.onclick=function(e){if(e){e.preventDefault();e.stopPropagation();}return false;};
    var burger=$('mobile-burger');
    if(burger){
      burger.onclick=function(e){ if(e){e.preventDefault();e.stopPropagation();} openDrawer(); return false; };
    }

    /* iOS Safari needs a non-passive touch guard while the drawer is open.
       It is attached only for that short period so ordinary page scrolling
       stays compositor-driven on mobile. */

    installTapVsScrollGuard('#gmob-drawer','.gmob-item,button,a');

    if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',ensureOneWebinarButton);
    else ensureOneWebinarButton();
    window.addEventListener('load',function(){setTimeout(ensureOneWebinarButton,300)});
  })();

  /* Dashboard drawers are owned by assets/js/controllers.js. Keeping a second
     owner here created delayed closes and duplicate touch/click decisions. */
})();

function toast(msg,type=''){
  const t=document.getElementById('toastbar');
  const bg={green:'#166534',red:'#991b1b',blue:'#1E72BE'}[type]||'#1a1a1a';
  t.textContent=msg; t.style.background=bg; t.className='toast-bar';
  setTimeout(()=>t.className='toast-bar on',10);
  setTimeout(()=>t.className='toast-bar',3400);
}

function setPaymentPageStatus(kind,title,detail){
  let box=document.getElementById('guidcy-payment-status');
  if(!box){
    const body=document.querySelector('#page-payment .pay-body');
    const button=body&&body.querySelector('.green-btn');
    if(body){box=document.createElement('div');box.id='guidcy-payment-status';box.className='guidcy-payment-status';body.insertBefore(box,button||null);}
  }
  if(!box)return;
  const esc=function(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})};
  kind=String(kind||'info').toLowerCase();
  box.className='guidcy-payment-status '+kind;
  box.setAttribute('role',kind==='error'?'alert':'status');
  box.setAttribute('aria-live',kind==='error'?'assertive':'polite');
  box.innerHTML='<strong>'+esc(title||'')+'</strong>'+(detail?'<span>'+esc(detail)+'</span>':'');
  box.hidden=false;
}
window.guidcySetPaymentPageStatus=setPaymentPageStatus;

/* An account that is a consultant can also book other consultants. The booking
   row is the same one the booked consultant sees - it is only ever looked up by
   user_id (booker) or consultant_id (booked). These two helpers decide which
   dashboard PANEL to paint, which is a UI question, not a visibility one. */
function guidcyRefreshMyBookings(userView){
  try{
    if(currentProfile&&currentProfile.role==='consultant'){swCD('my-bookings',null);return}
    swUD(userView||'upcoming',null);
  }catch(_){}
}
function guidcyGoToMyBookings(){
  const consultant=!!(currentProfile&&currentProfile.role==='consultant');
  try{go(consultant?'cons-dash':'user-dash');setTimeout(function(){guidcyRefreshMyBookings()},120)}catch(_){}
}
window.guidcyRefreshMyBookings=guidcyRefreshMyBookings;
window.guidcyGoToMyBookings=guidcyGoToMyBookings;

window.guidcyPaymentOutcomeAction=function(action){
  const booking=window.lastBooking||{};
  window.__guidcyPaymentFlowLock=false;
  const popup=document.getElementById('booking-confirm-popup');
  if(popup)popup.remove();
  if(action==='dashboard'){
    guidcyGoToMyBookings();
  }else if(action==='meet'&&/^https:\/\/meet\.google\.com\//i.test(String(booking.meet_link||''))){
    window.open(booking.meet_link,'_blank','noopener');
  }else if(typeof window.guidcyEnsurePaymentPageOnly==='function'){
    window.guidcyEnsurePaymentPageOnly();
  }
};

window.guidcyPaymentBack=function(){
  if(window.__guidcyPaymentFlowLock||window.__guidcyRazorpayBookingBusy){
    setPaymentPageStatus('processing','Payment is still in progress','Finish or cancel the secure checkout before leaving this page.');
    toast('Please finish or cancel the payment before leaving.','blue');
    if(typeof window.guidcyEnsurePaymentPageOnly==='function')window.guidcyEnsurePaymentPageOnly();
    return false;
  }
  history.back();
  return true;
};

