  const esc=function(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})};
  const meet=/^https:\/\/meet\.google\.com\//i.test(String(bk&&bk.meet_link||''))?String(bk.meet_link):'';
  const meetingPending=!meet;
  const div=document.createElement('div');
  div.id='booking-confirm-popup';
