/* Accept/Decline used to append `.catch()` to the write (see guidcySupabaseWrite),
   so the update threw before it was sent: the booking stayed pending in the
   database while the card said "Accepted" and the client was never notified.
   Only report success once the row has actually changed. */
async function acceptBookingReq(bookingId,idx){
  if(sb){
    const error=await window.guidcySupabaseWrite(sb.from('bookings').update({status:'confirmed'}).eq('id',bookingId));
    if(error){toast('Could not accept this booking: '+(error.message||'please try again'),'red');return;}
  }
  const sp=document.getElementById('req-s-'+idx);
  if(sp){sp.textContent='Accepted';sp.className='status-pill sp-upcoming';}
  toast('Booking accepted! Client notified ✓','green');
}
async function declineBookingReq(bookingId,idx){
  if(sb){
    const error=await window.guidcySupabaseWrite(sb.from('bookings').update({status:'cancelled',session_status:'cancelled'}).eq('id',bookingId));
    if(error){toast('Could not decline this booking: '+(error.message||'please try again'),'red');return;}
  }
  const item=document.getElementById('req-'+idx);if(item)item.style.opacity='.4';
  toast('Booking declined. Refund initiated.');
}
async function saveConsProfile(consId){
  if(!sb||!currentUser){toast('Not logged in','red');return;}
  const name=document.getElementById('cd-name')?.value||'';
  const specialty=document.getElementById('cd-title')?.value||'';
  const rate=parseInt(document.getElementById('cd-rate')?.value)||2000;
  const bio=document.getElementById('cd-bio')?.value||'';
  const updates={name,specialty,rate,bio};
  // If no consId passed, look up by profile_id
  let resolvedId=consId;
  if(!resolvedId){
    /* Superseded at runtime by a later saveConsProfile patch, but kept correct:
       the builder `.catch()` this used to carry threw before the request was
       sent (see guidcySupabaseWrite), so the base version silently saved
       nothing whenever consId had to be resolved. */
    try{
      const res=await sb.from('consultants').select('id').eq('profile_id',currentUser.id).maybeSingle();
      resolvedId=res&&res.data&&res.data.id;
    }catch(e){ console.warn('Consultant lookup failed:',e); }
  }
  if(resolvedId){
    const{error}=await sb.from('consultants').update(updates).eq('id',resolvedId);
    if(error){toast('Save failed: '+error.message,'red');return;}
  }
  const profileError=await window.guidcySupabaseWrite(sb.from('profiles').update({full_name:name,avatar_initials:mkInitials(name)}).eq('id',currentUser.id));
  if(profileError){toast('Save failed: '+(profileError.message||'please try again'),'red');return;}
  if(currentProfile){currentProfile.full_name=name;currentProfile.avatar_initials=mkInitials(name);}
  updateNav();
  toast('Profile saved ✓','green');
}
async function savePayoutDetails(consId){
  if(!sb||!consId){toast('Payout info saved ✓','green');return;}
  const error=await window.guidcySupabaseWrite(sb.from('consultants').update({bank_ifsc:document.getElementById('cd-ifsc')?.value||'',upi_id:document.getElementById('cd-upi')?.value||'',pan_number:document.getElementById('cd-pan')?.value||''}).eq('id',consId));
  if(error){toast('Could not save payout details: '+(error.message||'please try again'),'red');return;}
  toast('Payout details saved ✓','green');
}
function toggleDay(el){
  const on=el.dataset.on==='true';el.dataset.on=(!on).toString();
  el.style.background=!on?'var(--green)':'var(--border)';el.children[0].style.left=!on?'18px':'4px';
  const sel=el.parentNode.querySelector('select');if(sel){sel.disabled=on;sel.style.opacity=on?'.35':'1';}
}
// Opens the logged-in consultant's own public profile page
async function cancelBooking(bookingId, role){
  if(!bookingId||bookingId==='undefined'||bookingId===''||bookingId==='null'){
    toast('Cannot cancel — please refresh the page and try again','red');
    return;
  }
  if(!confirm('Cancel this session? This cannot be undone.'))return;
  if(!sb||!currentUser){toast('Not logged in','red');return;}
  // Try updating matching the bookingId + the current user's id (satisfies any RLS policy)
  const{data,error}=await sb.from('bookings')
    .update({status:'cancelled',session_status:'cancelled',cancelled_by:role,cancelled_at:new Date().toISOString()})
    .eq('id',bookingId)
    .select();
  if(error){toast('Cancel failed: '+error.message,'red');console.error(error);return;}
  if(!data||!data.length){
    // RLS might require matching on user_id — try with that too
    const{data:d2,error:e2}=await sb.from('bookings')
      .update({status:'cancelled',session_status:'cancelled',cancelled_by:role,cancelled_at:new Date().toISOString()})
      .eq('id',bookingId)
      .or(`user_id.eq.${currentUser.id},consultant_id.in.(select id from consultants where profile_id='${currentUser.id}')`)
      .select();
    if(e2||!d2||!d2.length){
      toast('Could not cancel — try again or contact guidcytechnologies@gmail.com','red');
      console.error('Cancel RLS failure',e2);
      return;
    }
  }
  if(lastBooking?.id===bookingId)lastBooking=null;
  toast('Session cancelled. View in Session History.','green');
  try{window.guidcyForceBookingStatusRefresh&&window.guidcyForceBookingStatusRefresh('user-cancel',bookingId,'cancelled',{id:bookingId,status:'cancelled',session_status:'cancelled',cancelled_by:role})}catch(_){}
  if(role==='user') guidcyRefreshMyBookings();
  else swCD('requests',null);
}

async function viewMyPublicProfile(){
  if(!currentUser||!sb){toast('Please log in first','red');return;}
  /* `.single().catch(...)` threw before the request was sent (a query builder is
     a thenable with no `catch`), so this button did nothing at all. maybeSingle()
     is also the right call here: it returns null instead of erroring when the
     consultant record does not exist yet, which is the case being handled. */
  let record=null;
  try{
    const res=await sb.from('consultants').select('id').eq('profile_id',currentUser.id).maybeSingle();
    if(res&&res.error)throw res.error;
    record=res&&res.data;
  }catch(e){
    console.warn('Could not look up your consultant profile:',e);
    toast('Could not open your public profile. Please try again.','red');
    return;
  }
  if(record?.id){
    await openProfile(record.id, null);
  } else {
    toast('Profile not found — please complete your settings first','red');
  }
}

// Opens a slot picker for a specific date
function openDateSlotPicker(dateKey,dateLabel){
  document.querySelectorAll('.avail-date-card').forEach(c=>c.classList.remove('sel-active'));
  const cardEl=document.querySelector(`.avail-date-card[data-date="${dateKey}"]`);
  if(cardEl)cardEl.classList.add('sel-active');
  const panel=document.getElementById('slot-picker-panel');if(!panel)return;
  const slots=guidcyFutureSlotsForDate(dateKey,window._allSlots||['9:00 AM','10:00 AM','11:00 AM','12:00 PM','2:00 PM','3:00 PM','4:00 PM','5:00 PM']);
  const selected=guidcyFutureSlotsForDate(dateKey,(window._availMap&&window._availMap[dateKey])||[]);
  if(window._availMap){if(selected.length)window._availMap[dateKey]=selected;else delete window._availMap[dateKey];}
  panel.innerHTML=`<div class="slot-picker-card">
    <div class="slot-picker-head">
      <div><div class="slot-picker-title">${dateLabel}</div><div style="font-size:12px;color:var(--muted);margin-top:2px">Click slots to mark yourself available</div></div>
      <div style="display:flex;gap:6px"><button class="btn" style="padding:6px 12px;font-size:12px" onclick="quickFillSlots('${dateKey}','morning')">+ Morning</button><button class="btn" style="padding:6px 12px;font-size:12px" onclick="quickFillSlots('${dateKey}','afternoon')">+ Afternoon</button><button class="btn" style="padding:6px 12px;font-size:12px" onclick="clearDateSlots('${dateKey}')">Clear</button></div>
    </div>
    <div class="slot-pick-grid">${slots.length?slots.map(s=>`<button class="slot-pick-btn ${selected.includes(s)?'on':''}" onclick="toggleSlotPick(this,'${dateKey}','${s}')">${s}</button>`).join(''):'<div style="grid-column:1/-1;color:var(--muted);font-size:12px;padding:8px 0">No future times remain for this date.</div>'}</div>
  </div>`;
}
function toggleSlotPick(btn,dateKey,slot){
  if(!window._availMap)window._availMap={};
  if(!window._availMap[dateKey])window._availMap[dateKey]=[];
  const arr=window._availMap[dateKey];
  const i=arr.indexOf(slot);
  if(i>=0){arr.splice(i,1);btn.classList.remove('on');}
  else{arr.push(slot);btn.classList.add('on');}
  if(arr.length===0)delete window._availMap[dateKey];
  // Update the date card count
  updateDateCardCount(dateKey);
}
function quickFillSlots(dateKey,which){
  const slots=window._allSlots||[];
  const morning=slots.filter(s=>{const h=parseInt(s);const pm=s.includes('PM');return !pm||h===12;}).filter(s=>{const h=parseInt(s);const pm=s.includes('PM');return (!pm&&h>=8)||(pm&&h===12);});
  const afternoon=slots.filter(s=>{const h=parseInt(s);const pm=s.includes('PM');return pm&&(h>=1||h===12);}).filter(s=>{const h=parseInt(s);return h>=1&&h<=6;}).concat(slots.filter(s=>s.includes('PM')&&(s.startsWith('5:')||s.startsWith('6:'))));
  const set=new Set(window._availMap[dateKey]||[]);
  const target=guidcyFutureSlotsForDate(dateKey,which==='morning'?['9:00 AM','10:00 AM','11:00 AM','12:00 PM']:['2:00 PM','3:00 PM','4:00 PM','5:00 PM']);
  target.forEach(s=>set.add(s));
  window._availMap[dateKey]=Array.from(set);
  // Refresh picker
  const card=document.querySelector(`.avail-date-card[data-date="${dateKey}"]`);
  const lbl=card?card.querySelector('.avail-date-num').textContent:dateKey;
  const dateObj=new Date(dateKey);
  openDateSlotPicker(dateKey,dateObj.toDateString());
  updateDateCardCount(dateKey);
}
function clearDateSlots(dateKey){
  if(window._availMap)delete window._availMap[dateKey];
  const dateObj=new Date(dateKey);
  openDateSlotPicker(dateKey,dateObj.toDateString());
  updateDateCardCount(dateKey);
}
function updateDateCardCount(dateKey){
  const card=document.querySelector(`.avail-date-card[data-date="${dateKey}"]`);if(!card)return;
  const slots=(window._availMap&&window._availMap[dateKey])||[];
  const countEl=card.querySelector('.avail-date-count');
  if(slots.length>0){
    card.classList.add('has-slots');
    if(countEl)countEl.textContent=slots.length+' slot'+(slots.length>1?'s':'');
  }else{
    card.classList.remove('has-slots');
    if(countEl)countEl.textContent='+ Add';
  }
}

async function saveSchedule(){
  if(!sb){toast('Not logged in','red');return;}
  const uid=currentUser?.id;
  if(!uid){toast('Not logged in','red');return;}
  const availMap=guidcyPruneAvailabilityMap(window._availMap||{});
  window._availMap=availMap;
  // Derive available_days (weekday names) and a flat slots list from the per-date map
  const dayMap=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  const daySet=new Set();const slotSet=new Set();
  Object.keys(availMap).forEach(k=>{
    const d=new Date(k);daySet.add(dayMap[d.getDay()]);
    (availMap[k]||[]).forEach(s=>slotSet.add(s));
  });
  const activeDays=Array.from(daySet);
  const activeSlots=Array.from(slotSet);
  const vp=parseInt(document.getElementById('price-video')?.value)||2000;
  const ap=parseInt(document.getElementById('price-audio')?.value)||Math.round(vp*0.75);
  const cp=parseInt(document.getElementById('price-chat')?.value)||Math.round(vp*0.5);
  const stypes=[];
  if(document.getElementById('offer-video')?.checked) stypes.push('video');
  if(document.getElementById('offer-audio')?.checked) stypes.push('audio');
  if(document.getElementById('offer-chat')?.checked) stypes.push('chat');
  try{
    const{error}=await sb.from('consultants').update({
      availability_map:availMap,
      available_days:activeDays,
      slots:activeSlots.length?activeSlots:['10:00 AM','2:00 PM','4:00 PM'],
      video_price:vp,audio_price:ap,chat_price:cp,
      rate:vp,session_types:stypes.length?stypes:['video']
    }).eq('profile_id',uid);
    if(error)throw error;
    toast('Availability & pricing saved!','green');
  }catch(e){
    toast('Error saving: '+(e.message||'try again'),'red');
    console.warn('saveSchedule error',e);
  }
}

