/* Admin call sites keep their shorter signature; see guidcyDashLoadFailed. */
function guidcyAdminLoadFailed(main,title,tab,error){
  return window.guidcyDashLoadFailed('swAD',main,title,tab,error);
}
window.guidcyAdminLoadFailed=guidcyAdminLoadFailed;

async function swAD(view,btn){
  if(btn){document.querySelectorAll('#page-admin-dash .side-btn').forEach(b=>b.classList.remove('on'));btn.classList.add('on');closeDashMenu('admin');}
  const m=document.getElementById('adash-main');if(!m)return;

  if(view==='overview'){
    let stats={users:0,sessions:0,consultants:0,pending:0};
    if(sb){
      const[u,b,c,p]=await Promise.all([
        sb.from('profiles').select('id',{count:'exact',head:true}),
        sb.from('bookings').select('id',{count:'exact',head:true}),
        sb.from('consultants').select('id',{count:'exact',head:true}).eq('is_active',true),
        sb.from('consultants').select('id',{count:'exact',head:true}).eq('is_active',false),
      ]);
      const failed=[u,b,c,p].find(r=>r&&r.error);
      if(failed)return guidcyAdminLoadFailed(m,'Analytics overview','overview',failed.error);
      stats={users:u.count||0,sessions:b.count||0,consultants:c.count||0,pending:p.count||0};
    }
    m.innerHTML=`<div class="dash-title">Analytics overview</div>
    <div class="admin-stats">
      <div class="admin-stat"><div class="admin-stat-val">${stats.users.toLocaleString()}</div><div class="admin-stat-lbl">Total users</div></div>
      <div class="admin-stat"><div class="admin-stat-val">${stats.sessions.toLocaleString()}</div><div class="admin-stat-lbl">Sessions booked</div></div>
      <div class="admin-stat"><div class="admin-stat-val">${stats.consultants}</div><div class="admin-stat-lbl">Active consultants</div></div>
      <div class="admin-stat" style="border-color:#F59E0B"><div class="admin-stat-val" style="color:#B45309">${stats.pending}</div><div class="admin-stat-lbl">Pending approvals</div>${stats.pending>0?`<button class="btn btn-blue" style="font-size:11px;padding:4px 10px;margin-top:8px" onclick="swAD('consultants',null)">Review now →</button>`:''}</div>
    </div>`;

  }else if(view==='consultants'){
    let consultants=[];
    if(sb){
      const{data,error}=await sb.from('consultants').select('*').order('created_at',{ascending:false});
      if(error)return guidcyAdminLoadFailed(m,'Manage Consultants','consultants',error);
      if(data)consultants=data;
    }
    const activeCount=consultants.filter(c=>c.is_active).length;
    const suspendedCount=consultants.filter(c=>!c.is_active).length;
    const rows=consultants.map((c,i)=>{
      const isActive=c.is_active;
      const statusCls=isActive?'sp-upcoming':'sp-cancelled';
      const statusTxt=isActive?'Active':'Suspended';
      const actions=isActive
        ?`<button class="action-btn ab-reject" onclick="suspendConsultant('${c.id||''}',${i})">Suspend</button>`
        :`<button class="action-btn ab-approve" onclick="approveConsultant('${c.id||''}',${i})">↑ Reinstate</button>`;
      const joined=c.created_at?new Date(c.created_at).toLocaleDateString('en-IN'):'—';
      return `<tr><td><div style="font-weight:600">${c.name}</div><div style="font-size:11px;color:var(--muted)">${c.experience||c.exp||''} ${c.specialty||c.category||''}</div></td><td>₹${(c.rate||c.price||0).toLocaleString()}</td><td>${joined}</td><td><span id="ad-s-${i}" class="status-pill ${statusCls}">${statusTxt}</span></td><td style="display:flex;gap:6px;flex-wrap:wrap">${actions}</td></tr>`;
    }).join('');
    const statsBar=`<div style="display:flex;gap:12px;margin-bottom:20px"><div style="background:var(--green-l);border:1px solid #B7F0BE;border-radius:var(--rs);padding:10px 20px;font-size:13px;color:var(--green-d);font-weight:600">${activeCount} Active</div><div style="background:#FCEBEB;border:1px solid #F9A8A8;border-radius:var(--rs);padding:10px 20px;font-size:13px;color:#A32D2D;font-weight:600">${suspendedCount} Suspended</div><div style="background:var(--surface2);border:1px solid var(--border);border-radius:var(--rs);padding:10px 20px;font-size:13px;color:var(--muted);font-weight:600">${consultants.length} Total</div></div>`;
    m.innerHTML=`<div class="dash-title">Manage Consultants</div>${statsBar}<table class="data-table"><tr><th>Name & Category</th><th>Rate/hr</th><th>Joined</th><th>Status</th><th>Actions</th></tr>${rows}${!rows?'<tr><td colspan="5" style="text-align:center;padding:32px;color:var(--muted)">No consultants registered yet</td></tr>':''}</table>`
  }else if(view==='bookings'){
    let bookings=[];
    if(sb){const{data,error}=await sb.from('bookings').select('*').order('created_at',{ascending:false}).limit(50);if(error)return guidcyAdminLoadFailed(m,'All bookings','bookings',error);bookings=data||[];}
    m.innerHTML=`<div class="dash-title">All bookings</div>
    <table class="data-table"><tr><th>Payment ID</th><th>Client</th><th>Consultant</th><th>Date</th><th>Amount</th><th>Status</th></tr>
    ${bookings.length?bookings.map(b=>{const bookingStatus=String(b.status||b.session_status||'pending').toLowerCase(),sessionStatus=String(b.session_status||'').toLowerCase(),isCancelled=['cancelled','canceled'].includes(bookingStatus)||['cancelled','canceled'].includes(sessionStatus),bookingLabel=isCancelled?'Cancelled':(bookingStatus||'Pending').replace(/_/g,' '),bookingClass=isCancelled?'sp-cancelled':bookingStatus==='completed'?'sp-done':(bookingStatus==='upcoming'||bookingStatus==='confirmed')?'sp-upcoming':'sp-pending',paymentStatus=String(b.payment_status||'').toLowerCase(),paymentLabel=(paymentStatus==='success'||paymentStatus==='paid'||paymentStatus==='refunded')?'Paid':paymentStatus==='failed'?'Failed':paymentStatus?'Pending':'Pending',refundStatus=String(b.refund_status||'not_required').toLowerCase(),refundLabel=({refund_pending:'Refund Pending',refund_processing:'Refund Processing',refunded:'Refunded',refund_failed:'Refund Failed',not_required:'Not Required'})[refundStatus]||'Not Required',payoutStatus=String(b.payout_status||'not_eligible').toLowerCase(),payoutLabel=({blocked:'Blocked',not_eligible:'Not Eligible',not_required:'Not Eligible',pending:'Payout Pending',paid:'Paid'})[payoutStatus]||'Not Eligible',cancelledLifecycle=isCancelled?`<div style="margin-top:6px;font-size:11px;line-height:1.45;color:var(--muted)">Payment: <b>${paymentLabel}</b> · Refund: <b>${refundLabel}</b> · Payout: <b>${payoutLabel}</b></div>`:'';return `<tr><td style="color:var(--blue);font-weight:600;font-size:11px">${b.payment_id||b.razorpay_payment_id||'—'}</td><td>${b.user_name||'—'}</td><td>${b.consultant_name||'—'}</td><td>${b.date_label||'—'}</td><td>₹${b.total_amount?.toLocaleString()||b.payment_amount?.toLocaleString()||'—'}</td><td><span class="status-pill ${bookingClass}">${bookingLabel}</span>${cancelledLifecycle}</td></tr>`}).join(''):`<tr><td colspan="6" style="text-align:center;color:var(--muted);padding:24px">No bookings yet</td></tr>`}
    </table>`;

  }else if(view==='users'){
    let users=[];
    if(sb){const{data,error}=await sb.from('profiles').select('*').order('created_at',{ascending:false}).limit(50);if(error)return guidcyAdminLoadFailed(m,'Manage users','users',error);users=data||[];}
    m.innerHTML=`<div class="dash-title">Manage users</div>
    <table class="data-table"><tr><th>Name</th><th>Email</th><th>Role</th><th>Joined</th><th>Actions</th></tr>
    ${users.length?users.map(u=>`<tr><td style="font-weight:600">${u.full_name||'—'}</td><td style="color:var(--muted);font-size:12px">${u.email||'—'}</td><td><span class="status-pill ${u.role==='admin'?'sp-pending':u.role==='consultant'?'sp-upcoming':'sp-done'}">${u.role}</span></td><td>${new Date(u.created_at).toLocaleDateString('en-IN')}</td><td><button class="action-btn ab-reject" onclick="toast('User suspended')">Suspend</button></td></tr>`).join(''):`<tr><td colspan="5" style="text-align:center;color:var(--muted);padding:24px">No users yet</td></tr>`}
    </table>`;

  }else if(view==='payments'){
    let bookings=[];
    if(sb){const{data,error}=await sb.from('bookings').select('*').order('created_at',{ascending:false}).limit(200);if(error)return guidcyAdminLoadFailed(m,'Payment management','payments',error);bookings=data||[];}
    const paid=bookings.filter(b=>String(b.payment_status||'').toLowerCase()==='success');
    const pendingPay=bookings.filter(b=>String(b.payment_status||'').toLowerCase()==='pending');
    const failedPay=bookings.filter(b=>String(b.payment_status||'').toLowerCase()==='failed');
    const gmv=paid.reduce((s,b)=>s+Number(b.total_amount||b.payment_amount||b.amount||0),0);
    // Guidcy keeps gross minus the consultant payout: the 5% client platform fee plus the 15% commission.
    const take=b=>window.guidcyBookingGuidcyTake?window.guidcyBookingGuidcyTake(b):0;
    const owed=b=>window.guidcyBookingPayable?window.guidcyBookingPayable(b):0;
    const rev=paid.reduce((s,b)=>s+take(b),0);
    const payoutDue=paid.reduce((s,b)=>String(b.payout_status||'').toLowerCase()==='paid'?s:s+owed(b),0);
    const payoutPaid=paid.reduce((s,b)=>String(b.payout_status||'').toLowerCase()==='paid'?s+owed(b):s,0);
    const rows=bookings.slice(0,80).map(b=>{
      const ps=String(b.payment_status||'').toLowerCase();
      const pillCls=ps==='success'?'sp-upcoming':ps==='failed'?'sp-cancelled':'sp-pending';
      const pillTxt=ps==='success'?'Success':ps==='failed'?'Failed':'Pending';
      const payoutTxt=ps!=='success'?'—':(String(b.payout_status||'pending').toLowerCase()==='paid'?'Paid':'Pending');
      return `<tr><td style="font-size:11px;color:var(--muted)">${b.created_at?new Date(b.created_at).toLocaleDateString('en-IN'):'—'}</td><td>${b.user_name||b.user_email||'—'}</td><td>${b.consultant_name||'—'}</td><td style="font-weight:600">₹${Number(b.total_amount||b.amount||0).toLocaleString()}</td><td><span class="status-pill ${pillCls}">${pillTxt}</span></td><td>${payoutTxt}</td><td style="font-size:11px;color:var(--muted)">${b.payment_id||b.razorpay_payment_id||b.payu_mihpayid||'—'}</td></tr>`;
    }).join('');
    m.innerHTML=`<div class="dash-title">Payment management</div>
    <div class="admin-stats" style="grid-template-columns:repeat(3,1fr)">
      <div class="admin-stat"><div class="admin-stat-val">₹${gmv.toLocaleString()}</div><div class="admin-stat-lbl">Total GMV (successful)</div></div>
      <div class="admin-stat"><div class="admin-stat-val">₹${rev.toLocaleString()}</div><div class="admin-stat-lbl">Platform revenue</div></div>
      <div class="admin-stat"><div class="admin-stat-val">${paid.length}</div><div class="admin-stat-lbl">Successful payments</div></div>
      <div class="admin-stat"><div class="admin-stat-val">₹${payoutDue.toLocaleString()}</div><div class="admin-stat-lbl">Consultant payouts due</div></div>
      <div class="admin-stat"><div class="admin-stat-val">₹${payoutPaid.toLocaleString()}</div><div class="admin-stat-lbl">Consultant payouts paid</div></div>
      <div class="admin-stat"><div class="admin-stat-val">${pendingPay.length} / ${failedPay.length}</div><div class="admin-stat-lbl">Pending / Failed payments</div></div>
    </div>
    <h3 style="font-family:'Cormorant Garamond',serif;font-size:22px;margin:22px 0 12px">Recent transactions</h3>
    <table class="data-table"><tr><th>Date</th><th>Client</th><th>Consultant</th><th>Amount</th><th>Payment</th><th>Payout</th><th>Reference</th></tr>
    ${rows||`<tr><td colspan="7" style="text-align:center;color:var(--muted);padding:24px">No bookings yet</td></tr>`}
    </table>`;

  }else{
    // Reviews moderation
    let reviews=[];
    if(sb){const{data,error}=await sb.from('reviews').select('*,consultants(name)').order('created_at',{ascending:false}).limit(30);if(error)return guidcyAdminLoadFailed(m,'Reviews moderation',String(view||'reviews'),error);reviews=data||[];}
    m.innerHTML=`<div class="dash-title">Reviews moderation</div>
    <table class="data-table"><tr><th>Reviewer</th><th>Consultant</th><th>Rating</th><th>Review</th><th>Actions</th></tr>
    ${reviews.length?reviews.map(r=>`<tr><td style="font-weight:600">${r.reviewer_name||'Anonymous'}</td><td>${r.consultants?.name||'—'}</td><td>${'★'.repeat(r.rating)}</td><td style="font-size:12px;max-width:200px">${(r.text||'').slice(0,80)}...</td><td><button class="action-btn ab-reject" onclick="removeReview('${r.id}')">Remove</button></td></tr>`).join(''):`<tr><td colspan="5" style="text-align:center;color:var(--muted);padding:24px">No reviews yet</td></tr>`}
    </table>`;
  }
}

/* Suspend, Reinstate and Remove review used to append `.catch()` to the write,
   which threw before the request was sent - see guidcySupabaseWrite above. */
const guidcyAdminWrite = window.guidcySupabaseWrite;
async function approveConsultant(consId,idx){
  if(sb && consId){
    const error=await guidcyAdminWrite(sb.from('consultants')
      /* is_active alone is no longer enough to be listed - the public query also
         requires approval_status/is_approved, so set them here too or this button
         reactivates an account that still stays invisible. */
      .update({approval_status:'approved', is_approved:true, is_active:true, badge:'verified',
               approved_at:new Date().toISOString(), approved_by:window.currentUser?.email||window.currentProfile?.email||'admin'})
      .eq('id',consId));
    if(error){toast('Approval failed: '+(error.message||'please try again'),'red');return;}
    // Notify the consultant via notifications table
    let cons=null;
    try{ const res=await sb.from('consultants').select('profile_id,name').eq('id',consId).maybeSingle(); cons=res&&res.data; }
    catch(e){ console.warn('Consultant lookup for approval notice failed:',e); }
    if(cons?.profile_id){
      const notifyError=await guidcyAdminWrite(sb.from('notifications').insert({
        user_id:cons.profile_id,
        text:`🎉 Congratulations! Your Guidcy consultant profile has been approved. You are now live and searchable by users.`,
        type:'approval'
      }));
      if(notifyError)console.warn('Approval notification not saved:',notifyError.message||notifyError);
    }
  }
  const sp=document.getElementById('ad-s-'+idx);
  if(sp){sp.textContent='Active';sp.className='status-pill sp-upcoming';}
  // Hide action buttons for this row
  const row=sp?.closest('tr');
  if(row){const td=row.querySelector('td:last-child');if(td)td.innerHTML='<span style="color:var(--green-d);font-size:12px">✓ Live on Guidcy</span>';}
  toast('Consultant approved and now live on Guidcy ✓','green');
}
async function suspendConsultant(consId,idx){
  if(sb&&consId){
    const error=await guidcyAdminWrite(sb.from('consultants').update({is_active:false,badge:'suspended'}).eq('id',consId));
    if(error){toast('Could not suspend this consultant: '+(error.message||'please try again'),'red');return;}
  }
  const sp=document.getElementById('ad-s-'+idx);
  if(sp){sp.textContent='Suspended';sp.className='status-pill sp-cancelled';}
  // Leave the row usable: the action for a suspended consultant is Reinstate.
  const row=sp?.closest('tr');
  if(row){const td=row.querySelector('td:last-child');if(td)td.innerHTML='<button class="action-btn ab-approve" onclick="approveConsultant(\''+String(consId||'').replace(/[\'"]/g,'')+'\','+(Number(idx)||0)+')">&uarr; Reinstate</button>';}
  toast('Consultant suspended');
}
async function removeReview(reviewId){
  if(sb&&reviewId){
    const error=await guidcyAdminWrite(sb.from('reviews').update({is_published:false}).eq('id',reviewId));
    if(error){toast('Could not remove this review: '+(error.message||'please try again'),'red');return;}
  }
  toast('Review removed');
}

/* ═══════════════════════════════════════════
   REVIEWS
═══════════════════════════════════════════ */
function openReviewPage(consId){
  reviewConsId=consId;reviewBookingId=null;
  document.getElementById('rv-cons-name').textContent='Consultant';
  document.getElementById('rv-session-meta').textContent='Recent session · 60 min';
  resetReview();go('review');
}
function openReviewPageForBooking(bookingId,consName,consId){
  reviewBookingId=bookingId;reviewConsId=consId;
  document.getElementById('rv-cons-name').textContent=consName;
  document.getElementById('rv-session-meta').textContent='Completed session';
  resetReview();go('review');
}
function resetReview(){
  curStars=0;recChoice=null;aspectStars={};
  document.querySelectorAll('.star-i').forEach(b=>b.className='star-i');
  document.getElementById('star-lbl').textContent='Tap a star to rate';
  document.getElementById('rv-aspects').style.display='none';
  document.getElementById('rv-text').value='';
  document.getElementById('rec-yes').className='btn';
  document.getElementById('rec-no').className='btn';
}
function setStars(n){
  curStars=n;
  document.querySelectorAll('.star-i').forEach((b,i)=>b.className='star-i'+(i<n?' lit':''));
  const labels=['','Disappointing','Below expectations','Decent','Good value','Exceptional! Highly recommend'];
  document.getElementById('star-lbl').textContent=n?labels[n]:'Tap a star to rate';
  if(n>=3){
    document.getElementById('rv-aspects').style.display='block';
    document.getElementById('aspect-grid').innerHTML=aspectNames.map(name=>`<div style="border:1px solid var(--border);border-radius:var(--rs);padding:10px;background:var(--surface)"><div style="font-size:11px;color:var(--muted);margin-bottom:6px">${name}</div><div style="display:flex;gap:2px">${[1,2,3,4,5].map(s=>`<button onclick="setAspect('${name}',${s},this.parentNode)" style="background:none;border:none;cursor:pointer;font-size:18px;color:${(aspectStars[name]||0)>=s?'#F59E0B':'var(--border2)'};padding:0;line-height:1">★</button>`).join('')}</div></div>`).join('');
  }else document.getElementById('rv-aspects').style.display='none';
}
function setAspect(name,val,c){aspectStars[name]=val;c.querySelectorAll('button').forEach((b,i)=>b.style.color=i<val?'#F59E0B':'var(--border2)');}
function setRec(c){recChoice=c;document.getElementById('rec-yes').className='btn'+(c==='yes'?' btn-blue':'');document.getElementById('rec-no').className='btn'+(c==='no'?' btn-dark':'');}

async function submitReview(){
  if(!curStars){toast('Please rate your session first','red');return;}
  const text=document.getElementById('rv-text').value.trim();
  if(text.length<10){toast('Please write at least a short review','red');return;}
  if(sb&&currentUser){
    const{error}=await sb.from('reviews').insert({
      user_id:currentUser.id,consultant_id:reviewConsId||null,booking_id:reviewBookingId||null,
      rating:curStars,text,recommend:recChoice==='yes',
      reviewer_name:currentProfile?.full_name||'Anonymous',
      aspect_ratings:aspectStars,is_published:true
    });
    if(error){toast('Could not save review: '+error.message,'red');return;}
  }
  toast('Review published! Thank you 🎉','green');
  setTimeout(()=>go('user-dash'),1000);
}

/* ═══════════════════════════════════════════
   CATEGORIES + FAQ
═══════════════════════════════════════════ */
async function initCategories(){
  const el=document.getElementById('cats-full-grid');if(!el)return;
  // Show skeleton first
  el.innerHTML=CATEGORIES_FULL.map(()=>`<div style="height:80px;background:var(--surface2);border-radius:12px;margin-bottom:14px;animation:pulse2 1.2s infinite"></div>`).join('');
  // Fetch real counts per category from DB
  const counts={};
  if(sb){
    try{
      const{data}=await sb.from('consultants').select('category,specialty').eq('is_active',true);
      (data||[]).forEach(c=>{
        const k=(c.category||c.specialty||'').toLowerCase();
        CATEGORIES_FULL.forEach(cat=>{
          const matchKey=cat.name.split(' ')[0].toLowerCase();
          if(k.includes(matchKey)) counts[cat.name]=(counts[cat.name]||0)+1;
        });
      });
    }catch(e){console.warn('Cat count fetch failed',e);}
  }
  el.innerHTML=CATEGORIES_FULL.map(cat=>{
    return `<div style="margin-bottom:28px"><div style="display:flex;align-items:center;gap:10px;margin-bottom:14px"><span style="font-size:24px">${cat.icon}</span><div><div style="font-family:'Cormorant Garamond',serif;font-size:20px;font-weight:500">${cat.name}</div></div><button class="btn btn-blue" style="margin-left:auto;font-size:12px;padding:6px 14px" onclick="filterAndBrowse('${cat.name.split(' ')[0]}')">Find experts →</button></div><div class="tag-list">${cat.subs.map(s=>`<span class="skill-tag" onclick="filterAndBrowse('${cat.name.split(' ')[0]}')" style="cursor:pointer">${s}</span>`).join('')}</div></div><hr style="border:none;border-top:1px solid var(--border);margin-bottom:28px"/>`;
  }).join('');
}
function initFAQ(){
  const render=(items,id)=>{const el=document.getElementById(id);if(!el)return;el.innerHTML=items.map(item=>`<div class="faq-item"><div class="faq-q" onclick="toggleFAQ(this)"><span>${item.q}</span><span class="faq-arrow">▾</span></div><div class="faq-a">${item.a}</div></div>`).join('');};
  render(FAQ_CLIENT,'faq-client');render(FAQ_CONSULTANT,'faq-consultant');
}
function toggleFAQ(el){
  const a=el.nextElementSibling,open=a.classList.contains('open');
  document.querySelectorAll('.faq-a.open').forEach(x=>{x.classList.remove('open');x.previousElementSibling.classList.remove('open');x.previousElementSibling.querySelector('.faq-arrow').classList.remove('open');});
  if(!open){a.classList.add('open');el.classList.add('open');el.querySelector('.faq-arrow').classList.add('open');}
}

/* ═══════════════════════════════════════════
   INIT
═══════════════════════════════════════════ */
function guidcyPlaceFooterAfterPages(){
  try{
    const footer=document.querySelector('.footer');
    if(!footer)return;
    const pages=Array.from(document.querySelectorAll('.page'));
    const active=document.querySelector('.page.on,.page.active');
    const lastPage=active||pages[pages.length-1];
    footer.hidden=false;
    footer.style.display='';
    footer.style.visibility='';
    footer.style.opacity='';
    if(lastPage&&lastPage.parentNode){
      lastPage.insertAdjacentElement('afterend',footer);
    }else{
      document.body.appendChild(footer);
    }
    if(window.__guidcyAllowFooterReady){
      requestAnimationFrame(function(){document.body.classList.add('guidcy-footer-ready')});
    }
  }catch(e){}
}
guidcyPlaceFooterAfterPages();
initAuth();
const initialPage=getPageFromPath();
const initialPathWithSearch=(window.location.pathname||'/')+(window.location.search||'');
window.__guidcyInitialPathWithSearch=initialPathWithSearch;
window.__guidcyInitialRouteExpires=Date.now()+15000;
const preserveInitialUrl=!!window.location.search || /^\/(admin\/webinar-registrations|consultant\/|book\/)/.test(window.location.pathname||'');
history.replaceState({page:initialPage}, '', preserveInitialUrl ? initialPathWithSearch : (PAGE_URLS[initialPage] || window.location.pathname || '/'));
renderPage(initialPage);
// Handle browser Back/Forward buttons
window.addEventListener('popstate', function(e){
  renderPage(e.state?.page || getPageFromPath());
});


/* ═══════════════════════════════════════════
   GUIDCY PATCH — reminders, dashboard notifications, filters
   Added by ChatGPT
═══════════════════════════════════════════ */

function guidcySafeId(v){return String(v||'').replace(/[^a-zA-Z0-9_-]/g,'_');}

function guidcyGetBookingDateTime(bk){
  try{
    const now=new Date();
    const monthMap={jan:0,january:0,feb:1,february:1,mar:2,march:2,apr:3,april:3,may:4,jun:5,june:5,jul:6,july:6,aug:7,august:7,sep:8,sept:8,september:8,oct:9,october:9,nov:10,november:10,dec:11,december:11};
    const dateLabel=String(bk?.date_label||'').trim();
    const timeSlot=String(bk?.time_slot||'').trim()||'11:59 PM';
    let yearMatch=dateLabel.match(/\b(20\d{2})\b/);
    let year=yearMatch?Number(yearMatch[1]):now.getFullYear();
    let clean=dateLabel.replace(/,?\s*20\d{2}/,'').trim();
    let m=clean.match(/([A-Za-z]+)\s+(\d{1,2})/)||clean.match(/(\d{1,2})\s+([A-Za-z]+)/);
    let month,day;
    if(m){
      if(isNaN(Number(m[1]))){month=monthMap[m[1].toLowerCase()];day=Number(m[2]);}
      else{day=Number(m[1]);month=monthMap[m[2].toLowerCase()];}
    }
    if(month===undefined||!day){
      const d=new Date(`${dateLabel} ${timeSlot}`);
      if(!isNaN(d.getTime()))return d;
      return null;
    }
    const t=timeSlot.match(/(\d{1,2})(?::(\d{2}))?\s*(AM|PM)?/i);
    let hr=t?Number(t[1]):0, min=t&&t[2]?Number(t[2]):0, ap=t&&t[3]?t[3].toUpperCase():'';
    if(ap==='PM'&&hr<12)hr+=12;
    if(ap==='AM'&&hr===12)hr=0;
    let dt=new Date(year,month,day,hr,min,0,0);
    if(!yearMatch && dt.getTime()<now.getTime()-86400000){dt=new Date(year+1,month,day,hr,min,0,0);}
    return isNaN(dt.getTime())?null:dt;
  }catch(e){console.warn('Booking date parse failed:',e);return null;}
}

async function guidcyFetchConsultantContact(consId){
  const out={email:null,profileId:null};
  try{
    if(!consId)return out;
    const cRes=await supabaseRest('consultants?id=eq.'+encodeURIComponent(consId)+'&select=id,profile_id,name',{method:'GET',timeoutMs:15000});
    const cRow=Array.isArray(cRes.data)?cRes.data[0]:cRes.data;
    out.profileId=cRow?.profile_id||null;
    if(!out.email && out.profileId){
      const pRes=await supabaseRest('profiles?id=eq.'+encodeURIComponent(out.profileId)+'&select=email',{method:'GET',timeoutMs:15000});
      const pRow=Array.isArray(pRes.data)?pRes.data[0]:pRes.data;
      out.email=pRow?.email||null;
    }
  }catch(e){console.warn('Could not fetch consultant contact:',e);}
  return out;
}

function guidcyReminderKey(bk,minutes,recipient){
  return `guidcy_reminder_${guidcySafeId(bk?.id||bk?.payment_id||bk?.booking_id)}_${minutes}_${recipient}`;
}
function guidcyCompletionKey(bk,recipient){
  return `guidcy_complete_${guidcySafeId(bk?.id||bk?.payment_id||bk?.booking_id)}_${recipient}`;
}

async function guidcySendBookingEmailTo(toEmail,toName,bk,role,mode='confirmation'){
  if(!toEmail)return {skipped:true};
  if(typeof window.sendGuidcyEmail!=='function')return {skipped:true,reason:'sendGuidcyEmail_unavailable'};
  const mins=mode==='reminder30'?30:mode==='reminder15'?15:null;
  const isReminder=mode.startsWith('reminder');
  const consultantName=bk.consultant_name||curCons?.name||'Consultant';
  const userName=bk.user_name||currentProfile?.full_name||'User';
  const type=isReminder?'session_reminder_user':(role==='consultant'?'new_booking_consultant':'booking_confirmed_user');
  return window.sendGuidcyEmail({
    to:toEmail,
    recipientName:toName||'Guidcy User',
    recipientRole:role,
    type,
    relatedTable:'bookings',
    relatedId:bk.id||bk.booking_id||null,
    data:{
      reminder_minutes:mins,
      user_name:userName,
      user_email:bk.user_email||currentUser?.email||'',
      consultant_name:consultantName,
      consultant_email:role==='consultant'?toEmail:(bk.consultant_email||''),
      date_label:bk.date_label||'',
      time_slot:bk.time_slot||'',
      duration:bk.duration||60,
      session_type:String(bk.session_type||'video').toUpperCase(),
      amount:bk.amount||bk.fee||0,
      total_amount:bk.total_amount||0,
      meet_link:bk.meet_link||'',
      action_link:bk.meet_link||(location.origin+'/user-dashboard'),
      payment_id:bk.payment_id||'',
      booking_id:bk.id||bk.booking_id||''
    }
  });
}

async function guidcySendReminderForBooking(bk,minutes,consultantEmail,consultantProfileId){
  const userEmail=(bk.user_email||currentUser?.email||'').trim();
  const userName=bk.user_name||currentProfile?.full_name||'User';
  const consultantName=bk.consultant_name||curCons?.name||'Consultant';
  const mode=minutes===30?'reminder30':'reminder15';
  const bookingId=bk.id||null;
  try{
    if(userEmail && !localStorage.getItem(guidcyReminderKey(bk,minutes,'user_email'))){
      await guidcySendBookingEmailTo(userEmail,userName,bk,'user',mode);
      localStorage.setItem(guidcyReminderKey(bk,minutes,'user_email'),'1');
    }
    if(consultantEmail && !localStorage.getItem(guidcyReminderKey(bk,minutes,'consultant_email'))){
      await guidcySendBookingEmailTo(consultantEmail,consultantName,bk,'consultant',mode);
      localStorage.setItem(guidcyReminderKey(bk,minutes,'consultant_email'),'1');
    }
    if(bk.user_id && !localStorage.getItem(guidcyReminderKey(bk,minutes,'user_notif'))){
      await insertNotificationDirect(bk.user_id,`⏰ Reminder: Your session with ${consultantName} starts in ${minutes} minutes.`, 'reminder', bookingId);
      localStorage.setItem(guidcyReminderKey(bk,minutes,'user_notif'),'1');
    }
    if(consultantProfileId && !localStorage.getItem(guidcyReminderKey(bk,minutes,'consultant_notif'))){
      await insertNotificationDirect(consultantProfileId,`⏰ Reminder: Your session with ${userName} starts in ${minutes} minutes.`, 'reminder', bookingId);
      localStorage.setItem(guidcyReminderKey(bk,minutes,'consultant_notif'),'1');
    }
  }catch(e){console.warn(`Reminder ${minutes} min failed:`,e);}
}

async function guidcyScheduleReminderTimersForBooking(bk,consultantEmail=null,consultantProfileId=null){
  const dt=guidcyGetBookingDateTime(bk);
  if(!dt)return;
  if((!consultantEmail||!consultantProfileId)&&bk.consultant_id){
    const contact=await guidcyFetchConsultantContact(bk.consultant_id);
    consultantEmail=consultantEmail||contact.email;
    consultantProfileId=consultantProfileId||contact.profileId;
  }
  [30,15].forEach(minutes=>{
    const fireAt=dt.getTime()-minutes*60000;
    const delay=fireAt-Date.now();
    if(delay>0 && delay<2147483647){
      const key=guidcyReminderKey(bk,minutes,'timer');
      if(!localStorage.getItem(key)){
        localStorage.setItem(key,'scheduled');
        setTimeout(()=>guidcySendReminderForBooking(bk,minutes,consultantEmail,consultantProfileId),delay);
        console.log(`✅ Scheduled ${minutes}-minute reminder in ${Math.round(delay/1000)} sec for booking`,bk.id||bk.payment_id);
      }
    }else if(delay<=0 && delay>-10*60000){
      guidcySendReminderForBooking(bk,minutes,consultantEmail,consultantProfileId);
    }
  });
}

async function guidcyCheckCompletedAndAskReview(bk){
  try{
    if(!bk||bk.status!=='upcoming')return;
    const dt=guidcyGetBookingDateTime(bk);if(!dt)return;
    const end=new Date(dt.getTime()+(Number(bk.duration)||60)*60000);
    if(Date.now()<=end.getTime())return;
    await supabaseRest('bookings?id=eq.'+encodeURIComponent(bk.id)+'&select=*',{method:'PATCH',body:{status:'completed'},prefer:'return=representation',timeoutMs:15000});
    if(bk.user_id && !localStorage.getItem(guidcyCompletionKey(bk,'user'))){
      await insertNotificationDirect(bk.user_id,`✅ Your session with ${bk.consultant_name||'consultant'} is completed. Please leave a review for the consultant.`, 'review', bk.id);
      localStorage.setItem(guidcyCompletionKey(bk,'user'),'1');
    }
    const contact=await guidcyFetchConsultantContact(bk.consultant_id);
    if(contact.profileId && !localStorage.getItem(guidcyCompletionKey(bk,'consultant'))){
      await insertNotificationDirect(contact.profileId,`✅ Session with ${bk.user_name||'client'} is completed.`, 'session', bk.id);
      localStorage.setItem(guidcyCompletionKey(bk,'consultant'),'1');
    }
  }catch(e){console.warn('Completion/review notification failed:',e);}
}

async function guidcyScanUpcomingBookingsAndSchedule(){
  if(!currentUser?.id)return;
  if(document.hidden)return;
  try{
    const uRes=await supabaseRest('bookings?user_id=eq.'+encodeURIComponent(currentUser.id)+'&status=eq.confirmed&select=*',{method:'GET',timeoutMs:20000});
    const userBookings=Array.isArray(uRes.data)?uRes.data:[];
    for(const bk of userBookings){
      await guidcyScheduleReminderTimersForBooking(bk);
      await guidcyCheckCompletedAndAskReview(bk);
    }
    const cRes=await supabaseRest('consultants?profile_id=eq.'+encodeURIComponent(currentUser.id)+'&select=id,profile_id',{method:'GET',timeoutMs:15000});
    const cRow=Array.isArray(cRes.data)?cRes.data[0]:cRes.data;
    if(cRow?.id){
      const bRes=await supabaseRest('bookings?consultant_id=eq.'+encodeURIComponent(cRow.id)+'&status=eq.confirmed&select=*',{method:'GET',timeoutMs:20000});
      const consBookings=Array.isArray(bRes.data)?bRes.data:[];
      for(const bk of consBookings){
        let consultantEmail=null;
        try{const pRes=await supabaseRest('profiles?id=eq.'+encodeURIComponent(cRow.profile_id)+'&select=email',{method:'GET',timeoutMs:15000});const pRow=Array.isArray(pRes.data)?pRes.data[0]:pRes.data;consultantEmail=pRow?.email||null;}catch(_){}
        await guidcyScheduleReminderTimersForBooking(bk,consultantEmail,cRow.profile_id);
        await guidcyCheckCompletedAndAskReview(bk);
      }
    }
  }catch(e){console.warn('Reminder scan failed:',e);}
}

async function saveBooking(payId,dateLabel,fee,tot,meetLink){
  meetLink=(meetLink||'').trim();
  if(!meetLink){toast('Meet link was not generated, so booking was not saved.','red');return null;}
  if(!currentUser?.id){toast('Please login again. Booking was not saved.','red');return null;}

  const consId=(typeof curCons?.dbId==='string'&&curCons.dbId)?curCons.dbId:(typeof curCons?.id==='string'?curCons.id:null);
  const bookingPayload={
    user_id:currentUser.id,
    consultant_id:consId,
    consultant_name:curCons?.name||'Consultant',
    user_name:currentProfile?.full_name||'Guest',
    user_email:currentUser.email||null,
    date_label:dateLabel,
    time_slot:selSlot,
    duration:selDur,
    session_type:selSType,
    amount:fee,
    platform_fee:Math.round(fee*.05),
    total_amount:tot,
    status:'confirmed',
    payment_id:payId,
    meet_link:meetLink
  };
  console.log('Saving booking payload:',bookingPayload);
  let savedRow=null;
  try{
    const insertResult=await supabaseRest('bookings?select=*',{method:'POST',body:bookingPayload,prefer:'return=representation',timeoutMs:30000});
    console.log('Supabase REST insert result:',insertResult);
    if(!insertResult.ok){toast('Booking not saved: '+(insertResult.data?.message||insertResult.raw||insertResult.statusText),'red');return null;}
    savedRow=Array.isArray(insertResult.data)?insertResult.data[0]:insertResult.data;
    if(!savedRow?.id){toast('Booking saved but ID was not returned.','red');return null;}
    lastBooking={...bookingPayload,...savedRow,meet_link:savedRow.meet_link||meetLink};

    await supabaseRest('bookings?id=eq.'+encodeURIComponent(savedRow.id)+'&select=id,meet_link',{method:'PATCH',body:{meet_link:meetLink},prefer:'return=representation',timeoutMs:30000});

    const contact=await guidcyFetchConsultantContact(consId);
    const userMsg=`✅ Order confirmed: Your ${selSType} session with ${bookingPayload.consultant_name} is scheduled for ${dateLabel} at ${selSlot} IST. Meet: ${meetLink}`;
    const consMsg=`📅 New order confirmed: ${bookingPayload.user_name} booked a ${selSType} session for ${dateLabel} at ${selSlot} IST. Meet: ${meetLink}`;
    await insertNotificationDirect(currentUser.id,userMsg,'booking',savedRow.id);
    if(contact.profileId)await insertNotificationDirect(contact.profileId,consMsg,'booking',savedRow.id);

    await guidcySendBookingEmailTo(bookingPayload.user_email,bookingPayload.user_name,lastBooking,'user','confirmation');
    if(contact.email)await guidcySendBookingEmailTo(contact.email,bookingPayload.consultant_name,{...lastBooking,consultant_email:contact.email},'consultant','confirmation');

    await guidcyScheduleReminderTimersForBooking(lastBooking,contact.email,contact.profileId);
    updateConfirmPage();
    showBookingConfirmationPopup(lastBooking);
    toast('Booking confirmed. Emails and reminders are scheduled.','green');
    setTimeout(()=>{try{guidcyRefreshMyBookings();}catch(_){ }},700);
    return lastBooking;
  }catch(e){
    console.error('Booking save/email/reminder failed:',e);
    toast('Booking failed: '+(e.message||e),'red');
    return null;
  }
}

const __guidcyOriginalSwCD=window.swCD;
window.swCD=async function(view,btn){
  if(btn){document.querySelectorAll('#page-cons-dash .side-btn').forEach(b=>b.classList.remove('on'));btn.classList.add('on');closeDashMenu('cons');}
  if(view!=='notifications')return __guidcyOriginalSwCD(view,btn);
  const m=document.getElementById('cdash-main');if(!m)return;
  const name=currentProfile?.full_name||'Consultant';
  const avEl=document.getElementById('cdash-av'),nmEl=document.getElementById('cdash-name');
  if(avEl)avEl.textContent=currentProfile?.avatar_initials||mkInitials(name);if(nmEl)nmEl.textContent=name;
  let list=[];
  try{
    const res=await supabaseRest('notifications?user_id=eq.'+encodeURIComponent(currentUser.id)+'&order=created_at.desc&limit=30&select=*',{method:'GET',timeoutMs:15000});
    if(!Array.isArray(res.data))throw (res&&res.error)||new Error('Notifications could not be read');
    list=res.data;
  }catch(e){
    // "No notifications yet" is not true when the read failed - say what happened.
    console.warn(e);
    return window.guidcyDashLoadFailed('swCD',m,'Notifications','notifications',e);
  }
  m.innerHTML=`<div class="dash-title">Notifications</div>${list.length?list.map(n=>`<div class="notif-item ${n.is_read?'':'unread'}"><div class="notif-dot ${n.is_read?'read':''}"></div><div style="flex:1"><div class="notif-body">${n.text}</div><div class="notif-time">${timeAgo(n.created_at)}</div></div></div>`).join(''):'<div style="text-align:center;padding:48px 20px;color:var(--muted)"><div style="font-size:36px;margin-bottom:12px">🔔</div><div style="font-weight:600;margin-bottom:6px;color:var(--ink)">No notifications yet</div><p style="font-size:13px">Booking confirmations, reminders, and completion updates will appear here.</p></div>'}`;
  if(list.some(n=>!n.is_read))supabaseRest('notifications?user_id=eq.'+encodeURIComponent(currentUser.id),{method:'PATCH',body:{is_read:true},timeoutMs:15000}).catch(()=>{});
};

function guidcyInstallConsultantNotificationButton(){
  const side=document.querySelector('#page-cons-dash .side-nav');if(!side||document.getElementById('cons-notification-btn'))return;
  const divider=side.querySelector('.side-divider');
  const btn=document.createElement('button');
  btn.className='side-btn';btn.id='cons-notification-btn';btn.dataset.dashSection='notifications';btn.onclick=function(){swCD('notifications',this)};
  btn.innerHTML=`<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 0 1-3.46 0"/></svg>Notifications`;
  if(divider)side.insertBefore(btn,divider);else side.appendChild(btn);
}

async function applyFilters(){
  const panel=document.querySelector('#page-browse .filter-panel');
  const cats=[],stypes=[],langs=[],exp=[];
  if(panel){
    panel.querySelectorAll('.filter-section').forEach(sec=>{
      const title=(sec.querySelector('.filter-title')?.textContent||'').toLowerCase();
      sec.querySelectorAll('input[type=checkbox]:checked').forEach(cb=>{
        if(title.includes('categor'))cats.push(cb.value);
        else if(title.includes('session'))stypes.push(cb.value);
        else if(title.includes('language'))langs.push(cb.value);
        else if(title.includes('experience'))exp.push(cb.value);
      });
    });
  }
  const ratingChecked=panel?.querySelector('input[name="rating-f"]:checked');
  const priceRange=document.getElementById('price-range');
  const q=(document.getElementById('browse-search')?.value||document.getElementById('srch')?.value||browseFilters.search||'').trim();
  browseFilters={categories:cats,sessionTypes:stypes,languages:langs,experience:exp,minRating:ratingChecked?Number(ratingChecked.value)||0:0,minPrice:0,maxPrice:priceRange?Number(priceRange.value)||99999:99999,search:q};
  const g=document.getElementById('browse-grid');if(g)g.innerHTML='<div style="grid-column:1/-1;text-align:center;padding:40px;color:var(--muted)">Filtering experts...</div>';
  let list=await fetchConsultants(browseFilters);
  if(exp.length){
    list=list.filter(c=>{
      const txt=String(c.experience||c.exp||'').toLowerCase();
      const num=parseFloat(txt.match(/\d+/)?.[0]||'0');
      return exp.some(e=>e==='10+'?num>=10:e==='5+'?num>=5:true);
    });
  }
  renderGrid(list,'browse-grid');
  const active=document.getElementById('active-filters');
  if(active){
    const pills=[...cats,...stypes,...langs,...exp, browseFilters.minRating?`${browseFilters.minRating}+ rating`:null, q?`Search: ${q}`:null].filter(Boolean);
    active.innerHTML=pills.map(p=>`<span class="filter-pill">${p}</span>`).join('');
  }
}

function clearFilters(){
  document.querySelectorAll('#page-browse .filter-check input[type=checkbox]').forEach(cb=>cb.checked=false);
  document.querySelectorAll('#page-browse input[name="rating-f"]').forEach(r=>r.checked=(r.value==='0'));
  const pr=document.getElementById('price-range');if(pr){pr.value=pr.max||8000;const pv=document.getElementById('price-val');if(pv)pv.textContent='₹'+pr.value;}
  const bs=document.getElementById('browse-search');if(bs)bs.value='';
  browseFilters={categories:[],sessionTypes:[],languages:[],experience:[],minRating:0,minPrice:0,maxPrice:99999,search:''};
  applyFilters();
}

function doHeroSearch(){
  const q=(document.getElementById('srch')?.value||'').trim();
  const cat=document.getElementById('cat-select')?.value||'';
  if(cat){filterAndBrowse(cat);return;}
  browseFilters={...(browseFilters||{}),search:q};
  go('browse');
  setTimeout(applyFilters,150);
}

