/* ═══════════════════════════════════════════
   GUIDCY SEARCH + FILTER FIX — FINAL OVERRIDE
═══════════════════════════════════════════ */
let guidcyBrowseSuggestCache=[];
/* Company history arrives in half a dozen shapes: a plain string, a JSON string,
   or an array of {company_name,start_date,...}. Flatten to the values only -
   including object keys would make "company" or "date" match every consultant. */
function guidcyFlatText(v,d){
  d=d||0; if(v==null||d>4)return '';
  if(typeof v==='string'){ const t=v.trim(); if(t[0]==='['||t[0]==='{'){ try{return guidcyFlatText(JSON.parse(t),d+1)}catch(_){return t} } return t; }
  if(typeof v!=='object')return String(v);
  return Object.values(v).map(x=>guidcyFlatText(x,d+1)).join(' ');
}
function guidcyConsultantCompanyText(c){
  return guidcyFlatText([c.current_company_college,c.current_company,c.current_work,c.company_experience,
    c.experience_history,c.previous_companies,c.previous_company_experience,c.experience_companies_normalized,
    c.highest_education,c.college]);
}
/* Photo when one is uploaded, initials only as the fallback - same rule as reviews. */
function guidcySuggestAvatar(c){
  const ini=c.initials||c.avatar_initials||(typeof mkInitials==='function'?mkInitials(c.name):'');
  const bg=c.bg||c.avatar_bg||'#EBF4FF';
  const color=c.color||c.avatar_color||'#1E72BE';
  const url=c.avatar_url||c.profile_image_url||c.photo_url||c.image_url||c.profile_photo||c.image||'';
  return `<div class="search-suggest-avatar" style="background:${guidcyEscHtml(bg)};color:${guidcyEscHtml(color)}">${guidcyEscHtml(ini)}${url?`<img src="${guidcyEscHtml(url)}" alt="" loading="lazy" decoding="async" onerror="this.remove()">`:''}</div>`;
}
function guidcyText(v){ if(v===null||v===undefined)return ''; if(Array.isArray(v))return v.join(' '); return String(v); }
function guidcyConsultantSearchText(c){ return [c.name,c.role,c.specialty,c.category,c.bio,c.exp,c.experience,c.tags,c.certs,c.languages,c.sessionTypes,c.session_types,c.headline,guidcyConsultantCompanyText(c)].map(guidcyText).join(' ').toLowerCase(); }
async function guidcyGetAllConsultantsForSearch(){ try{ let list=await fetchConsultants({maxPrice:99999}); if(Array.isArray(list)&&list.length)return list; }catch(e){console.warn('Search candidate fetch failed',e);} return Array.isArray(SEED_CONSULTANTS)?SEED_CONSULTANTS:[]; }
function hideBrowseSuggestions(){ const box=document.getElementById('browse-search-suggestions'); if(box)box.classList.remove('on'); }
function guidcyEscHtml(t){return String(t||'').replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]));}
/* The grid stays strict, but a dropdown holding one result looks broken. Top it
   up to 5: best relevance score first (that covers typos), then whatever the
   cache already ranked highest. */
function guidcyPadSuggestions(hits,q,min,max){
  const out=hits.slice(0,max);
  if(out.length>=min)return out;
  const seen=new Set(out);
  const score=c=>{try{return window.guidcyConsultantScore?window.guidcyConsultantScore(c,q):0}catch(_){return 0}};
  const rest=guidcyBrowseSuggestCache.filter(c=>!seen.has(c)).map(c=>({c,s:score(c)}));
  rest.sort((a,b)=>b.s-a.s);
  for(const r of rest){ if(out.length>=min)break; out.push(r.c); }
  return out;
}
async function renderBrowseSuggestions(){
  const input=document.getElementById('browse-search')||document.getElementById('browse-srch');
  const box=document.getElementById('browse-search-suggestions');
  if(!input||!box)return;
  const q=(input.value||'').trim().toLowerCase();
  if(!q){box.classList.remove('on');box.innerHTML='';return;}
  if(!guidcyBrowseSuggestCache.length)guidcyBrowseSuggestCache=await guidcyGetAllConsultantsForSearch();
  const hits=guidcyBrowseSuggestCache.filter(c=>guidcyConsultantSearchText(c).includes(q));
  const list=guidcyPadSuggestions(hits,q,5,7);
  if(!hits.length&&!list.length){
    box.innerHTML=`<div class="search-suggest-item" onmousedown="event.preventDefault();clearFilters();const i=document.getElementById('browse-search');if(i)i.value='${guidcyEscHtml(q)}';browseFilters.search='${guidcyEscHtml(q)}';applyFilters();hideBrowseSuggestions();"><div class="search-suggest-avatar">🔍</div><div><div class="search-suggest-name">Search all for “${guidcyEscHtml(q)}”</div><div class="search-suggest-role">No exact recommendation found. Click to clear filters and search all consultants.</div></div></div>`;
    box.classList.add('on'); return;
  }
  box.innerHTML=list.map(c=>{
    const id=String(c.dbId||c.id||'').replace(/'/g,"\\'");
    const local=(typeof c.id==='number')?c.id:-1;
    const name=String(c.name||'Consultant').replace(/'/g,"\\'");
    return `<div class="search-suggest-item" onmousedown="event.preventDefault();selectBrowseSuggestion('${id}',${local},'${name}')">
      ${guidcySuggestAvatar(c)}
      <div style="min-width:0;flex:1"><div class="search-suggest-name">${guidcyEscHtml(c.name||'Consultant')}</div><div class="search-suggest-role">${guidcyEscHtml(c.role||c.specialty||c.category||'Consultant')}${c.price?' · ₹'+Number(c.price).toLocaleString():''}</div></div>
      <div class="search-suggest-hint">Open</div>
    </div>`;
  }).join('');
  box.classList.add('on');
}
function selectBrowseSuggestion(id,localId,name){ const input=document.getElementById('browse-search')||document.getElementById('browse-srch'); if(input)input.value=name||''; hideBrowseSuggestions(); openProfile(id,localId); }
/* The browse filter panel is torn down and re-rendered (unchecked) every time
   the page initialises, which threw away a category chosen on the Categories
   page. Whoever rebuilds the list calls this straight after to put the current
   selection back before anything reads the panel. */
function guidcyBrowseCatKey(value){
  var v=value;
  try{if(typeof window.guidcyCanonicalCategory==='function')v=window.guidcyCanonicalCategory(value)}catch(_){}
  return String(v==null?'':v).toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,' ').trim();
}
function guidcySyncBrowseCategoryChecks(){
  var list=document.getElementById('filter-cat-list'); if(!list)return;
  var sel=(window.browseFilters&&Array.isArray(window.browseFilters.categories))?window.browseFilters.categories:[];
  var wanted=sel.map(guidcyBrowseCatKey).filter(Boolean);
  list.querySelectorAll('input[type=checkbox]').forEach(function(cb){
    cb.checked=wanted.indexOf(guidcyBrowseCatKey(cb.value))!==-1;
  });
}
window.guidcySyncBrowseCategoryChecks=guidcySyncBrowseCategoryChecks;
/* Blank box = that end is unbounded, so an untouched filter shows every price.
   An out-of-order max is ignored rather than swapped, so typing a max digit by
   digit ("1" on the way to "12000") never briefly wipes the results. */
function guidcyPriceBounds(minEl,maxEl){
  const minPrice=Math.max(0,Number(minEl&&minEl.value)||0);
  const rawMax=Number(maxEl&&maxEl.value)||0;
  const maxPrice=(rawMax>0&&rawMax>=minPrice)?rawMax:99999;
  return {minPrice,maxPrice};
}
let guidcyPriceTimer=null;
function guidcyPriceInput(){ clearTimeout(guidcyPriceTimer); guidcyPriceTimer=setTimeout(applyFilters,350); }
function guidcyReadBrowseFilters(){
  const panel=document.querySelector('#page-browse .filter-panel'); const cats=[],stypes=[],langs=[],exp=[];
  if(panel){ panel.querySelectorAll('.filter-section').forEach(sec=>{ const title=(sec.querySelector('.filter-title')?.textContent||'').toLowerCase(); sec.querySelectorAll('input[type=checkbox]:checked').forEach(cb=>{ if(title.includes('categor'))cats.push(cb.value); else if(title.includes('session'))stypes.push(cb.value); else if(title.includes('language'))langs.push(cb.value); else if(title.includes('experience'))exp.push(cb.value); }); }); }
  const ratingChecked=panel?.querySelector('input[name="rating-f"]:checked'); const priceMinEl=document.getElementById('price-min'); const priceMaxEl=document.getElementById('price-max'); const sortValue=document.getElementById('sort-select')?.value||''; const input=document.getElementById('browse-search')||document.getElementById('browse-srch'); const q=(input?input.value:(browseFilters.search||'')).trim();   /* an emptied box is falsy - falling back to browseFilters.search kept the deleted query alive */
  return {categories:cats,sessionTypes:stypes,languages:langs,experience:exp,minRating:ratingChecked?Number(ratingChecked.value)||0:0,...guidcyPriceBounds(priceMinEl,priceMaxEl),search:q,sort:sortValue};
}
window.__guidcyFilterRun=Number(window.__guidcyFilterRun)||0;
async function applyFilters(){
  /* Navigating to a category fires several applyFilters() runs (page init, the
     go() patch, filterAndBrowse). They resolve out of order, so the last one to
     come back used to repaint the grid - which is how an older, wider result
     landed on top of the correct one. Only the newest run may touch the DOM. */
  const run=++window.__guidcyFilterRun;
  const f=guidcyReadBrowseFilters(); browseFilters=f;
  const g=document.getElementById('browse-grid'); if(g)g.innerHTML='<div style="grid-column:1/-1;text-align:center;padding:40px;color:var(--muted)"><div style="font-size:28px;margin-bottom:8px">⏳</div>Searching experts...</div>';
  /* Blank the count too, or the previous category's number stays on screen
     next to a loading grid. */
  const loadingCount=document.getElementById('browse-count'); if(loadingCount)loadingCount.textContent='Loading experts...';
  let list=[]; try{list=await fetchConsultants(f);}catch(e){console.error('Filter failed',e);list=[];}
  if(run!==window.__guidcyFilterRun)return;
  if(f.experience?.length){ list=list.filter(c=>{ const txt=String(c.experience||c.exp||'').toLowerCase(); const num=parseFloat(txt.match(/\d+/)?.[0]||'0'); return f.experience.some(e=>e==='10+'?num>=10:e==='5+'?num>=5:true); }); }
  if(f.sort==='rating')list.sort((a,b)=>(b.rating||0)-(a.rating||0)); if(f.sort==='reviews')list.sort((a,b)=>(b.reviews||0)-(a.reviews||0)); if(f.sort==='price_asc')list.sort((a,b)=>(a.price||0)-(b.price||0)); if(f.sort==='price_desc')list.sort((a,b)=>(b.price||0)-(a.price||0));
  /* renderGrid drops anything that fails the approved check, so count what it
     actually drew rather than what we handed it. */
  const shown=renderGrid(list,'browse-grid');
  const n=Array.isArray(shown)?shown.length:list.length;
  const count=document.getElementById('browse-count'); if(count)count.textContent=`Showing ${n} expert${n===1?'':'s'}`;
  const active=document.getElementById('active-filters'); if(active){ const pills=[...f.categories,...f.sessionTypes,...f.languages,...f.experience,f.minRating?`${f.minRating}+ rating`:null,f.search?`Search: ${guidcyEscHtml(f.search)}`:null].filter(Boolean); active.innerHTML=pills.map(p=>`<span class="filter-pill">${p}<button onclick="clearFilters()">×</button></span>`).join(''); }
}
let guidcyBrowseSearchTimer=null;
function guidcyToggleSearchClear(){ const i=document.getElementById('browse-search'),b=document.getElementById('browse-search-clear'); if(b)b.hidden=!(i&&i.value.trim()); }
function guidcySyncClearedSearchUrl(){
  try{
    const params=new URLSearchParams(location.search);
    params.delete('q');
    params.delete('search');
    const category=params.get('category')||'';
    sessionStorage.setItem('guidcy_shared_search',JSON.stringify({q:'',category,at:Date.now()}));
    history.replaceState(Object.assign({},history.state||{},{q:'',category}),'',location.pathname+(params.toString()?`?${params.toString()}`:''));
  }catch(_){}
}
function guidcyClearSearch(){
  const i=document.getElementById('browse-search');
  if(i){i.value='';i.focus();}
  if(window.browseFilters)browseFilters.search='';
  guidcySyncClearedSearchUrl();
  hideBrowseSuggestions();
  guidcyToggleSearchClear();
  applyFilters();
}
function browseSearch(){ clearTimeout(guidcyBrowseSearchTimer); guidcyToggleSearchClear(); renderBrowseSuggestions(); guidcyBrowseSearchTimer=setTimeout(()=>applyFilters(),220); }
function browseSort(value){ browseFilters.sort=value||''; applyFilters(); }
function clearFilters(){ document.querySelectorAll('#page-browse .filter-check input[type=checkbox]').forEach(cb=>cb.checked=false); document.querySelectorAll('#page-browse input[name="rating-f"]').forEach(r=>r.checked=(r.value==='0')); const pmin=document.getElementById('price-min'); if(pmin)pmin.value=''; const pmax=document.getElementById('price-max'); if(pmax)pmax.value=''; const bs=document.getElementById('browse-search')||document.getElementById('browse-srch'); if(bs)bs.value=''; const ss=document.getElementById('sort-select');if(ss)ss.value=''; browseFilters={categories:[],sessionTypes:[],languages:[],experience:[],minRating:0,minPrice:0,maxPrice:99999,search:'',sort:''}; guidcySyncClearedSearchUrl(); hideBrowseSuggestions(); guidcyToggleSearchClear(); applyFilters(); }
async function initBrowse(){ const catList=document.getElementById('filter-cat-list'); if(catList && !catList.innerHTML.trim()){ catList.innerHTML=CATEGORIES_FULL.map(c=>{ const v=c.name.split(' ')[0]; return `<label class="filter-check"><input type="checkbox" value="${v}" onchange="applyFilters()"/> ${c.icon} ${c.name}</label>`; }).join(''); } const input=document.getElementById('browse-search')||document.getElementById('browse-srch'); if(input && browseFilters.search)input.value=browseFilters.search; await applyFilters(); }
async function filterAndBrowse(category){ browseFilters={categories:[category],sessionTypes:[],languages:[],experience:[],minRating:0,minPrice:0,maxPrice:99999,search:'',sort:''}; go('browse'); setTimeout(()=>{ document.querySelectorAll('#page-browse .filter-section input[type=checkbox]').forEach(cb=>{ cb.checked=(String(cb.value).toLowerCase()===String(category).toLowerCase()); }); const input=document.getElementById('browse-search')||document.getElementById('browse-srch'); if(input)input.value=''; applyFilters(); },180); }
let guidcyHeroSearchTimer=null;
function hideHeroSuggestions(){ const box=document.getElementById('hero-search-suggestions'); if(box)box.classList.remove('on'); }
function renderHeroSuggestions(){
  const input=document.getElementById('srch');
  const box=document.getElementById('hero-search-suggestions');
  if(!input||!box)return;
  const q=(input.value||'').trim().toLowerCase();
  const cat=(document.getElementById('cat-select')?.value||'').trim().toLowerCase();
  const source=[...(consultants||[]),...(dbConsultants||[])];
  const seen=new Set();
  let matches=source.filter(c=>{
    const id=String(c.dbId||c.id||c.name||'');
    if(seen.has(id))return false; seen.add(id);
    const text=[c.name,c.role,c.specialty,c.category,c.bio,(c.skills||[]).join(' '),(c.languages||[]).join(' ')].join(' ').toLowerCase();
    const catOk=!cat || String(c.category||'').toLowerCase().includes(cat) || text.includes(cat);
    const qOk=!q || text.includes(q);
    return catOk && qOk;
  }).slice(0,7);
  if(!q && !cat){
    matches=source.filter((c,i)=>i<6);
  }
  if(!matches.length){
    const label=input.value||document.getElementById('cat-select')?.value||'experts';
    box.innerHTML=`<div class="search-suggest-item" onmousedown="event.preventDefault();hideHeroSuggestions();doHeroSearch();"><div class="search-suggest-avatar">🔍</div><div><div class="search-suggest-name">Search for “${guidcyEscHtml(label)}”</div><div class="search-suggest-role">Open Browse page and search all available consultants.</div></div></div>`;
    box.classList.add('on');
    return;
  }
  box.innerHTML=matches.map(c=>{
    const id=String(c.dbId||c.id||'');
    const local=typeof c.id==='number'?c.id:'null';
    const name=String(c.name||'Consultant').replace(/'/g,"\'");
    return `<div class="search-suggest-item" onmousedown="event.preventDefault();selectHeroSuggestion('${id}',${local},'${name}')">
      ${guidcySuggestAvatar(c)}
      <div style="min-width:0;flex:1"><div class="search-suggest-name">${guidcyEscHtml(c.name||'Consultant')}</div><div class="search-suggest-role">${guidcyEscHtml(c.role||c.specialty||c.category||'Consultant')}${c.price?' · ₹'+Number(c.price).toLocaleString():''}</div></div>
      <div class="search-suggest-hint">Open</div>
    </div>`;
  }).join('');
  box.classList.add('on');
}
function selectHeroSuggestion(id,localId,name){ const input=document.getElementById('srch'); if(input)input.value=name||''; hideHeroSuggestions(); openProfile(id,localId); }
function heroSearchInput(){ clearTimeout(guidcyHeroSearchTimer); renderHeroSuggestions(); guidcyHeroSearchTimer=setTimeout(()=>{},120); }
function doHeroSearch(){ const q=(document.getElementById('srch')?.value||'').trim(); const cat=document.getElementById('cat-select')?.value||''; hideHeroSuggestions(); if(cat && !q){filterAndBrowse(cat);return;} browseFilters={categories:cat?[cat]:[],sessionTypes:[],languages:[],experience:[],minRating:0,minPrice:0,maxPrice:99999,search:q,sort:''}; go('browse'); setTimeout(()=>{const input=document.getElementById('browse-search')||document.getElementById('browse-srch');if(input)input.value=q; document.querySelectorAll('#page-browse .filter-section input[type=checkbox]').forEach(cb=>{ cb.checked=cat && String(cb.value).toLowerCase()===String(cat).toLowerCase(); }); applyFilters();},180); }
document.addEventListener('click',e=>{ const browseWrap=e.target.closest?.('.search-suggest-wrap'); const heroWrap=e.target.closest?.('.hero-search'); if(!browseWrap)hideBrowseSuggestions(); if(!heroWrap)hideHeroSuggestions(); });

/* ═══════════════════════════════════════════════════════════════
   GUIDCY PATCH — LATEST PRICING + PAYOUT/REFUND DETAILS
═══════════════════════════════════════════════════════════════ */
async function fetchLatestConsultantForBooking(consultantId){
  if(!consultantId || !CFG?.supabase_url || !CFG?.supabase_key) return null;
  try{
    const res=await supabaseRest('consultants?id=eq.'+encodeURIComponent(consultantId)+'&select=*',{method:'GET',timeoutMs:20000});
    if(!res.ok){console.warn('Latest consultant fetch failed:',res);return null;}
    const row=Array.isArray(res.data)?res.data[0]:res.data;
    if(!row) return null;
    return {...curCons,...row,id:row.id,dbId:row.id,name:row.name||curCons?.name||'Consultant',role:row.specialty||row.category||curCons?.role||'Consultant',price:row.video_price||row.rate||curCons?.price||2000,video_price:row.video_price||row.rate||curCons?.video_price||curCons?.price||2000,audio_price:row.audio_price||curCons?.audio_price||Math.round((row.video_price||row.rate||curCons?.price||2000)*0.75),chat_price:row.chat_price||curCons?.chat_price||Math.round((row.video_price||row.rate||curCons?.price||2000)*0.5),sessionTypes:row.session_types||curCons?.sessionTypes||['video'],availabilityMap:row.availability_map||curCons?.availabilityMap||{},avail:row.available_days||curCons?.avail||[],slots:row.slots||curCons?.slots||['10:00 AM','2:00 PM','4:00 PM']};
  }catch(e){console.warn('Latest consultant fetch exception:',e);return null;}
}
async function refreshCurrentConsultantBeforePayment(){
  const id=curCons?.dbId||curCons?.id;
  if(!id) return curCons;
  const latest=await fetchLatestConsultantForBooking(id);
  if(latest){curCons=latest;console.log('✅ Latest consultant pricing loaded before payment:',{consultant_id:curCons.id,video_price:curCons.video_price,audio_price:curCons.audio_price,chat_price:curCons.chat_price,rate:curCons.rate});}
  return curCons;
}
function getBookingFeeFromLatest(){return Math.round(getSTypePrice(curCons)*getDurMultiplier());}
function renderPaymentSummaryWithLatest(fee,totalAmount,dateLabel){
  const pfee=Math.round(fee*.05);
  const payAmt=document.getElementById('pay-amt');
  const payDesc=document.getElementById('pay-desc');
  const paySummary=document.getElementById('pay-summary-box');
  if(payAmt)payAmt.textContent='₹'+totalAmount.toLocaleString();
  if(payDesc)payDesc.textContent=`${selDur}-min ${selSType} session with ${curCons.name}`;
  if(paySummary){paySummary.innerHTML=`<div class="pay-sum-row"><span>Consultant</span><span>${curCons.name}</span></div><div class="pay-sum-row"><span>Date & time</span><span>${dateLabel} · ${selSlot} IST</span></div><div class="pay-sum-row"><span>Session type</span><span>${selSType==='video'?'📹 Video':selSType==='audio'?'📞 Audio':'💬 Chat'}</span></div><div class="pay-sum-row"><span>Duration</span><span>${selDur} min</span></div><div class="pay-sum-row"><span>Session fee</span><span>₹${fee.toLocaleString()}</span></div><div class="pay-sum-row"><span>Platform fee (5%)</span><span>₹${pfee.toLocaleString()}</span></div><div class="pay-sum-row final"><span>Total due</span><span>₹${totalAmount.toLocaleString()}</span></div>`;}
}
startBooking=async function(){
  if(!selSlot){toast('Please select a time slot','red');return;}
  if(!currentUser&&!loggedIn&&sb){toast('Please log in to book');setTimeout(()=>go('login'),800);return;}
  const btn=document.querySelector('.book-footer .green-btn');const old=btn?btn.textContent:'';
  if(btn){btn.disabled=true;btn.textContent='Loading latest price...';}
  await refreshCurrentConsultantBeforePayment();
  if(btn){btn.disabled=false;btn.textContent=old||'Book this session';}
  const dates=buildDates();const fee=getBookingFeeFromLatest();const pfee=Math.round(fee*.05),tot=fee+pfee;const dateLabel=dates[selDate]?.full||dates[selDate]?.label||'';
  renderPaymentSummaryWithLatest(fee,tot,dateLabel);go('payment');
};
