/* === Guidcy targeted fix pack: admin login, blog route, category expansion, photo refresh, button stability === */
(function(){
  const ADMIN_EMAIL=(window.CFG&&CFG.admin_email?String(CFG.admin_email):'tripathiprakhar41@gmail.com').trim().toLowerCase();
  function gid(x){return document.getElementById(x)}
  function isAdminEmail(email){return String(email||'').trim().toLowerCase()===ADMIN_EMAIL}
  function safeInitials(n){try{return (typeof mkInitials==='function'?mkInitials(n):String(n||'U').split(/\s+/).map(s=>s[0]).join('').slice(0,2).toUpperCase())}catch(_){return 'U'}}
  function setCP(p){try{currentProfile=p}catch(_){window.currentProfile=p}try{loggedIn=p?.role||null}catch(_){window.loggedIn=p?.role||null}}
  function setCU(u){try{currentUser=u}catch(_){window.currentUser=u}}
  window.guidcyEnsureAdminProfile=async function(user){
    if(!user||!user.id) return null;
    const email=String(user.email||'').trim();
    try{
      let row=null;
      if(typeof sb!=='undefined'&&sb){
        const r=await sb.from('profiles').select('*').eq('id',user.id).maybeSingle();
        row=r.data||null;
        const meta=user.user_metadata||{};
        const name=row?.full_name||meta.full_name||meta.name||email.split('@')[0]||'Admin';
        const role=isAdminEmail(email)?'admin':(row?.role||meta.role||'user');
        const up={id:user.id,email,full_name:name,role,avatar_initials:row?.avatar_initials||safeInitials(name),avatar_url:row?.avatar_url||meta.avatar_url||''};
        await sb.from('profiles').upsert({...row,...up});
        row={...row,...up};
      }else{
        row={id:user.id,email,full_name:isAdminEmail(email)?'Admin':(email.split('@')[0]||'User'),role:isAdminEmail(email)?'admin':'user',avatar_initials:isAdminEmail(email)?'AD':'U'};
      }
      setCP(row); return row;
    }catch(e){
      const fallback={id:user.id,email,full_name:isAdminEmail(email)?'Admin':(email.split('@')[0]||'User'),role:isAdminEmail(email)?'admin':'user',avatar_initials:isAdminEmail(email)?'AD':'U'};
      setCP(fallback); return fallback;
    }
  };
  window.loadProfile=async function(){
    const u=(typeof currentUser!=='undefined'&&currentUser)||null;
    if(!u) return;
    return await window.guidcyEnsureAdminProfile(u);
  };
  window.doLogin=async function(){
    const email=(gid('li-email')?.value||'').trim();
    const pass=gid('li-pass')?.value||'';
    if(!email||!pass){try{toast('Enter your email and password','red')}catch(_){alert('Enter your email and password')}return;}
    const btn=document.querySelector('#page-login .primary-btn'); if(btn){btn.disabled=true;btn.textContent='Signing in...'}
    try{
      if(typeof sb!=='undefined'&&sb){
        const {data,error}=await sb.auth.signInWithPassword({email,password:pass});
        if(error) throw error;
        setCU(data.user); const profile=await window.guidcyEnsureAdminProfile(data.user);
        try{updateNav()}catch(_){}
        try{toast('Welcome back!','green')}catch(_){}
        setTimeout(()=>{try{go(profile?.role==='admin'?'admin-dash':profile?.role==='consultant'?'cons-dash':'user-dash')}catch(_){location.href=profile?.role==='admin'?'/admin':'/dashboard'}},250);
      }else{
        const role=(loginType==='admin'||isAdminEmail(email)||email.toLowerCase().includes('admin'))?'admin':(loginType==='consultant'?'consultant':'user');
        setCP({full_name:role==='admin'?'Admin':(role==='consultant'?'Consultant':'User'),role,avatar_initials:role==='admin'?'AD':(role==='consultant'?'CN':'US')});
        try{updateNav();toast('Signed in demo mode','blue')}catch(_){}
        setTimeout(()=>go(role==='admin'?'admin-dash':role==='consultant'?'cons-dash':'user-dash'),250);
      }
    }catch(e){console.error(e);try{toast(e.message||'Sign in failed','red')}catch(_){alert(e.message||'Sign in failed')}}
    if(btn){btn.disabled=false;btn.textContent='Sign in'}
  };

  const moreCats=['Medical','Entertainment','Social Media','Agriculture','Fashion','Startup','Music','Freelancing','Manufacturing','R&D','Education','Technology','Legal','Marketing','Real Estate','Travel','Fitness','Parenting','Government Exam','Study Abroad','Data Science','Artificial Intelligence','HR & Recruitment','Personal Finance','Taxation','Design','Content Creation','E-commerce','Sustainability & ESG'];
  function addOption(sel,cat){ if(!sel||Array.from(sel.options).some(o=>o.value===cat||o.textContent===cat)) return; const o=document.createElement('option'); o.value=cat; o.textContent=cat; sel.appendChild(o); }
  window.guidcyExpandCategories=function(){
    moreCats.forEach(c=>{addOption(gid('cat-select'),c); addOption(gid('sc-cat'),c);});
    const catPage=document.querySelector('#page-categories .cats-grid');
    if(catPage && !catPage.dataset.expanded){
      catPage.dataset.expanded='1';
      moreCats.forEach(c=>{const card=document.createElement('div');card.className='cat-card';card.onclick=()=>{try{filterAndBrowse(c)}catch(_){}};card.innerHTML=`<div class="cat-icon">${c==='Medical'?'🩺':c==='Agriculture'?'🌾':c==='Fashion'?'👗':c==='Music'?'🎵':c==='Manufacturing'?'🏭':c==='R&D'?'🔬':'✨'}</div><h3>${c}</h3><p>Connect with verified ${c} experts.</p>`;catPage.appendChild(card);});
    }
    const homeGrid=document.querySelector('.home-cats-grid');
    if(homeGrid && !homeGrid.dataset.morecats){
      homeGrid.dataset.morecats='1';
      ['Medical','Startup','Manufacturing','R&D','Social Media','Agriculture'].forEach(c=>{const card=document.createElement('div');card.className='home-cat-card';card.onclick=()=>{try{filterAndBrowse(c)}catch(_){}};card.innerHTML=`<div class="home-cat-icon" style="background:#EBF4FF;font-size:24px">${c==='Medical'?'🩺':c==='Manufacturing'?'🏭':c==='R&D'?'🔬':c==='Agriculture'?'🌾':'✨'}</div><div class="home-cat-name">${c}</div><div class="home-cat-count">Explore experts →</div>`;homeGrid.insertBefore(card,homeGrid.lastElementChild);});
    }
  };
  document.addEventListener('DOMContentLoaded',()=>setTimeout(window.guidcyExpandCategories,100));
  setTimeout(window.guidcyExpandCategories,800);

  // Blog page as SPA section if the main app is open
  window.guidcyBlogPosts=()=>JSON.parse(localStorage.getItem('guidcy_blog_posts')||'[]');
  window.guidcySaveBlogPosts=(p)=>localStorage.setItem('guidcy_blog_posts',JSON.stringify(p));
  window.renderGuidcyBlog=function(){
    const page=gid('page-blog'); if(!page) return;
    const posts=window.guidcyBlogPosts(); const role=(window.currentProfile&&currentProfile.role)||window.loggedIn||'';
    page.innerHTML=`<div style="max-width:1000px;margin:0 auto;padding:50px 20px"><h1 style="font-family:'Cormorant Garamond',serif;font-size:44px;margin-bottom:8px">Guidcy Blog</h1><p style="color:var(--muted);margin-bottom:26px">Insights from Guidcy. Admin can publish posts; users and consultants can comment.</p>${role==='admin'?`<div style="background:#fff;border:1px solid var(--border);border-radius:18px;padding:18px;margin-bottom:24px"><div class="field"><label>Blog title</label><input id="blog-title" placeholder="Enter blog title"></div><div class="field"><label>Blog content</label><textarea id="blog-body" style="min-height:140px" placeholder="Write your blog here"></textarea></div><button class="primary-btn" onclick="guidcyAddBlogPost()">Publish Blog</button></div>`:''}<div id="blog-list">${posts.length?posts.map((p,i)=>`<article style="background:#fff;border:1px solid var(--border);border-radius:18px;padding:20px;margin-bottom:16px"><h2 style="font-size:24px;margin-bottom:6px;color:var(--ink)">${p.title}</h2><div style="font-size:12px;color:var(--muted);margin-bottom:14px">${p.date}</div><p style="white-space:pre-wrap;color:#42576b">${p.body}</p><div style="margin-top:16px;border-top:1px solid var(--border);padding-top:14px"><h4 style="color:var(--blue);margin-bottom:10px">Comments</h4>${(p.comments||[]).map(c=>`<div style="background:#F8FBFF;border:1px solid #E6F1FB;border-radius:12px;padding:10px;margin:8px 0"><b>${c.name}</b><p style="margin:4px 0 0;color:#42576b">${c.text}</p></div>`).join('')||'<p style="color:var(--muted);font-size:13px">No comments yet.</p>'}<div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap"><input id="comment-${i}" placeholder="Write a comment" style="flex:1;min-width:220px;height:42px;border:1px solid var(--border);border-radius:12px;padding:0 12px"><button class="btn btn-blue" onclick="guidcyAddComment(${i})">Comment</button></div></div></article>`).join(''):'<div style="background:#fff;border:1px dashed var(--border);border-radius:18px;padding:30px;color:var(--muted);text-align:center">No blog posts yet.</div>'}</div></div>`;
  };
  window.guidcyAddBlogPost=function(){const t=gid('blog-title')?.value.trim(),b=gid('blog-body')?.value.trim(); if(!t||!b){toast('Please add blog title and content','red');return} const posts=window.guidcyBlogPosts(); posts.unshift({title:t,body:b,date:new Date().toLocaleDateString('en-IN'),comments:[]}); window.guidcySaveBlogPosts(posts); window.renderGuidcyBlog(); toast('Blog published','green')};
  window.guidcyAddComment=function(i){const inp=gid('comment-'+i); const txt=inp?.value.trim(); if(!txt)return; const posts=window.guidcyBlogPosts(); const name=(window.currentProfile&&currentProfile.full_name)||'Guest'; posts[i].comments=posts[i].comments||[]; posts[i].comments.push({name,text:txt}); window.guidcySaveBlogPosts(posts); window.renderGuidcyBlog();};
  const oldGo=window.go;
  window.go=function(p){ if(p==='blog'){let page=gid('page-blog'); if(!page){page=document.createElement('div');page.id='page-blog';page.className='page';document.body.appendChild(page);} document.querySelectorAll('.page').forEach(x=>x.classList.remove('active')); page.classList.add('active'); history.pushState(null,'','/blog'); window.renderGuidcyBlog(); try{closeMobileMenu()}catch(_){} return;} return oldGo?oldGo(p):null; };
})();


