  // 3) Enter key on login should submit sign-in.
  function enableEnterLogin(){['li-email','li-pass'].forEach(id=>{const el=$(id); if(el&&!el.dataset.enterLogin){el.dataset.enterLogin='1';el.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();doLogin();}})}})}

  // 4) Profile/dashboard name + image rendering.
  function paintAvatar(el,url,txt){if(!el)return;url=String(url||''); if(url){el.style.backgroundImage=`url("${url}")`;el.style.backgroundSize='cover';el.style.backgroundPosition='center';el.textContent='';}else{el.style.backgroundImage='';el.textContent=txt||'';}}
  window.refreshGuidcyProfileUI=function(){
    const p=cp(), u=cu();
    const name=p.full_name || (u?.user_metadata?.full_name||u?.user_metadata?.name) || (u?.email?u.email.split('@')[0]:'User');
    const av=p.avatar_url || u?.user_metadata?.avatar_url || u?.user_metadata?.picture || '';
    const ini=p.avatar_initials || initials(name);
    [['udash-av','udash-name'],['cdash-av','cdash-name']].forEach(([a,n])=>{paintAvatar($(a),av,ini); const nm=$(n); if(nm)nm.textContent=name;});
    document.querySelectorAll('.avatar-chip').forEach(ch=>{if(av){ch.style.backgroundImage=`url("${av}")`;ch.style.backgroundSize='cover';ch.style.backgroundPosition='center';ch.textContent='';}});
  };
  const oldLoad=window.loadProfile;
  window.loadProfile=async function(){
    if(oldLoad) await oldLoad();
    const u=cu(); if(!u)return;
    let p=cp()||{};
    const meta=u.user_metadata||{};
    const name=p.full_name || meta.full_name || meta.name || (u.email?u.email.split('@')[0]:'User');
    const avatar=p.avatar_url || meta.avatar_url || meta.picture || '';
    const role=String(u.email||'').toLowerCase()===ADMIN_EMAIL?'admin':(p.role||meta.role||'user');
    p={...p,id:u.id,email:u.email,full_name:name,avatar_url:avatar,avatar_initials:p.avatar_initials||initials(name),role};
    setCP(p); setLI(role);
    try{if(window.sb||typeof sb!=='undefined'){await (window.sb||sb).from('profiles').upsert({id:u.id,email:u.email,full_name:name,role,avatar_url:avatar,avatar_initials:p.avatar_initials})}}catch(e){}
    setTimeout(refreshGuidcyProfileUI,20);
  };
  const oldUpdateNav=window.updateNav;
