  function addOption(sel,name){if(!sel)return; if([...sel.options].some(o=>o.value===name||o.textContent.trim()===name))return; const o=document.createElement('option');o.value=name;o.textContent=name;sel.appendChild(o);}
  function categoryIcon(name){return (EXTRA_CATS.find(x=>x[1]===name)||['✨'])[0];}
