      var btn=document.createElement('button'); btn.type='button'; btn.className='guidcy-pass-toggle'; btn.textContent='Show';
      btn.onclick=function(ev){ev.preventDefault(); ev.stopPropagation(); inp.type=(inp.type==='password')?'text':'password'; btn.textContent=(inp.type==='password')?'Show':'Hide'; inp.focus();};
