    '/jobs':'jobs','/find-jobs':'jobs',
    '/careers':'careers','/find-work':'careers','/work':'careers','/guidcy-work':'careers',
    '/marketplace':'marketplace',
    '/categories':'categories','/blog':'blog',
    '/webinar':'webinar','/webinars':'webinar',
