  function saveTab(i){
    if(!i||!i.tab)return;
    try{
      if(i.page==='admin-dash')sessionStorage.setItem('guidcy_admin_dash_tab',i.tab)
      if(i.page==='user-dash')sessionStorage.setItem('guidcy_user_dash_tab',i.tab)
      if(i.page==='cons-dash')sessionStorage.setItem('guidcy_cons_dash_tab',i.tab)
    }catch(_){}
  }
