      if(i.tab&&i.page==='admin-dash'&&typeof window.swAD==='function')setTimeout(function(){try{window.swAD(i.tab,null)}catch(_){}},260);
      if(i.tab&&i.page==='user-dash'&&typeof window.swUD==='function')setTimeout(function(){try{window.swUD(i.tab,null)}catch(_){}},260);
      if(i.tab&&i.page==='cons-dash'&&typeof window.swCD==='function')setTimeout(function(){try{window.swCD(i.tab,null)}catch(_){}},260);
      keepUrl(i);
      if(i.page!=='home'&&activePage()==='home')setTimeout(function(){try{window.renderPage&&window.renderPage(i.page);keepUrl(i)}catch(_){}},180);
