  const oldGo=window.go;
  window.go=function(page){
    if(page==='webinar'){
      document.querySelectorAll('.page').forEach(p=>{p.classList.remove('on');p.classList.remove('active')});
      const el=document.getElementById('page-webinar'); if(el){el.classList.add('on');el.classList.add('active')}
      try{history.pushState(null,'','/webinars')}catch(e){}
      try{closeMobileMenu()}catch(e){}; try{closeMobDrawer()}catch(e){}; window.scrollTo(0,0);
      // Render webinar cards and admin panel AFTER page is visible
      try{if(typeof wbnRender==='function'){wbnRender();wbnApplyAdminState();}}catch(e){}
      setTimeout(function(){try{if(typeof wbnRender==='function'){wbnRender();wbnApplyAdminState();}}catch(e){}},100);
      return;
    }
    if(page==='blog'){
      renderInfoPages();window.renderGuidcyBlog();
      const key='blog';
      document.querySelectorAll('.page').forEach(p=>{p.classList.remove('on');p.classList.remove('active')});
      const el=id('page-'+key); if(el){el.classList.add('on');el.classList.add('active')}
      try{history.pushState(null,'','/blog')}catch(e){}
      try{closeMobileMenu()}catch(e){}; try{closeMobDrawer()}catch(e){}; window.scrollTo(0,0); return;
    }
    if(page==='help'||page==='help-center'){
      document.querySelectorAll('.page').forEach(p=>{p.classList.remove('on');p.classList.remove('active')});
      const el=document.getElementById('page-help'); if(el){el.classList.add('on');el.classList.add('active')}
      try{history.pushState(null,'','/help-center')}catch(e){}
      try{closeMobileMenu()}catch(e){}; try{closeMobDrawer()}catch(e){}; window.scrollTo(0,0); return;
    }
    if(page==='dispute'||page==='dispute-resolution'){
      document.querySelectorAll('.page').forEach(p=>{p.classList.remove('on');p.classList.remove('active')});
      const el=document.getElementById('page-dispute'); if(el){el.classList.add('on');el.classList.add('active')}
      try{history.pushState(null,'','/dispute-resolution')}catch(e){}
      try{closeMobileMenu()}catch(e){}; try{closeMobDrawer()}catch(e){}; window.scrollTo(0,0); return;
    }
    return oldGo?oldGo(page):undefined;
  };

  function fixFooter(){
    const fb=document.querySelector('.footer-brand');
    if(fb && !fb.querySelector('.guidcy-footer-text')) fb.insertAdjacentHTML('afterbegin','<div class="guidcy-footer-text"><span>Guid</span><span>cy</span></div>');
    document.querySelectorAll('.footer-col a').forEach(a=>{if((a.textContent||'').trim()==='Help Center')a.setAttribute('onclick',"go('help')"); if((a.textContent||'').trim()==='Dispute Resolution')a.setAttribute('onclick',"go('dispute')")});
    const cols=[...document.querySelectorAll('.footer-col')]; const support=cols.find(c=>/Support|Company|Legal/i.test(c.querySelector('h4')?.textContent||''))||cols[cols.length-1];
    if(support){
      // Links already in static footer — just ensure handlers are correct, no duplicates added
      support.querySelectorAll('a').forEach(a=>{
        if(/Help Cent(er|re)/i.test(a.textContent.trim())) a.setAttribute('onclick',"go('help')");
        if(/Dispute Resolution/i.test(a.textContent.trim())) a.setAttribute('onclick',"go('dispute')");
      });
    }
  }

