  function readBankForm(){var pref=el('cd-payout-preference')?.value||'bank_transfer'; var acct=(el('cd-account-number')?.value||'').replace(/\s+/g,''); var conf=(el('cd-account-confirm')?.value||'').replace(/\s+/g,''); var ifsc=(el('cd-ifsc-code')?.value||'').replace(/\s+/g,'').toUpperCase(); var payload={account_holder_name:(el('cd-account-holder')?.value||'').trim(),bank_name:(el('cd-bank-name')?.value||'').trim(),account_number:acct,ifsc_code:ifsc,upi_id:(el('cd-upi-id')?.value||'').trim(),pan_number:(el('cd-pan-number')?.value||'').trim().toUpperCase(),payout_preference:pref}; return {payload:payload,confirmAccount:conf}}
