      if(!existing && body.consultant_user_id){try{var byUid=await c.from('consultant_bank_details').select('id,consultant_id,consultant_user_id,updated_at').eq('consultant_user_id',body.consultant_user_id).order('updated_at',{ascending:false}).limit(1); if(!byUid.error && byUid.data && byUid.data[0])existing=byUid.data[0];}catch(_){}}
