  var resolveConsultantError=null;
  async function resolveConsultant(){var c=client(), uid=userId();resolveConsultantError=null;if(!c||!uid)return null;try{var r=await c.from('consultants').select('*').eq('profile_id',uid).limit(1);if(r.error)resolveConsultantError=r.error;else if(r.data?.[0])return r.data[0]}catch(e){resolveConsultantError=e}try{var r2=await c.from('consultants').select('*').eq('id',uid).limit(1);if(r2.error)resolveConsultantError=r2.error;else if(r2.data?.[0])return r2.data[0]}catch(e2){resolveConsultantError=e2}return null}
