	    var rows=settled.map(function(x){return x&&x.status==='fulfilled'?x.value:null}).filter(Boolean);
	    var profile=rows.find(function(r){return Object.prototype.hasOwnProperty.call(r,'is_admin')||Object.prototype.hasOwnProperty.call(r,'role')})||null;
	    var consultant=rows.find(function(r){return Object.prototype.hasOwnProperty.call(r,'approval_status')||Object.prototype.hasOwnProperty.call(r,'consultant_status')||Object.prototype.hasOwnProperty.call(r,'profile_status')||Object.prototype.hasOwnProperty.call(r,'specialty')})||null;
	    var profileRole=low(profile&&profile.role);
