	    var name=(profile&&(profile.full_name||profile.name))||(consultant&&(consultant.name||consultant.full_name))||(user&&user.user_metadata&&(user.user_metadata.full_name||user.user_metadata.name))||(email?email.split('@')[0]:'User');
	    var merged=Object.assign({},profile||{},role==='consultant'&&consultant?consultant:{},{id:id,email:email,role:role,full_name:name,avatar_initials:(profile&&profile.avatar_initials)||(consultant&&consultant.avatar_initials)||initials(name,role),avatar_url:(profile&&profile.avatar_url)||(consultant&&consultant.avatar_url)||(user&&user.user_metadata&&user.user_metadata.avatar_url)||''});
