(function(){
  'use strict';
  if(window.__GUIDCY_FINAL_FUNDS_GRANTS_RETURN_GUARD__)return;
  window.__GUIDCY_FINAL_FUNDS_GRANTS_RETURN_GUARD__=true;
  var STATE_KEY='guidcy_opp_last_state_v1';
  var EXTERNAL_KEY='guidcy_opp_external_open_v1';
  function read(k){try{return JSON.parse(sessionStorage.getItem(k)||'null')}catch(_){return null}}
  function write(k,v){try{sessionStorage.setItem(k,JSON.stringify(v))}catch(_){}}
  function recentExternal(){
    var s=read(EXTERNAL_KEY);
    return !!(s&&s.ts&&Date.now()-Number(s.ts)<30*60*1000&&read(STATE_KEY));
  }
  function markExternal(){
    try{
      if(typeof window.oppDoSearch==='function'){
        write(EXTERNAL_KEY,{ts:Date.now(),path:'/funds-grants'});
      }
    }catch(_){}
  }
  function restoreFundsRoute(){
    if(!recentExternal())return false;
    var path=(location.pathname||'/').replace(/\/+$/,'')||'/';
    if(!/^\/(?:funds-grants|opportunities)$/.test(path))return false;
    try{setTimeout(function(){window.initOpportunitiesFinder&&window.initOpportunitiesFinder()},100)}catch(_){}
    return true;
  }
  document.addEventListener('click',function(e){
    var a=e.target&&e.target.closest&&e.target.closest('#page-opportunities a[href]');
    if(!a)return;
    try{
      var u=new URL(a.getAttribute('href')||'',location.href);
      if(u.origin!==location.origin)markExternal();
    }catch(_){}
  },true);
  /* External-link state restores data only; it never intercepts navigation. */
  window.addEventListener('pageshow',function(){setTimeout(restoreFundsRoute,80)});
  window.addEventListener('focus',function(){setTimeout(restoreFundsRoute,80)});
  document.addEventListener('visibilitychange',function(){if(!document.hidden&&window.__guidcyVisRefreshOK('fundsRoute'))setTimeout(restoreFundsRoute,80)});
  [80,250,700,1400,2600].forEach(function(ms){setTimeout(restoreFundsRoute,ms)});
})();


