    var p=normalizePromo({code:$('guidcy-admin-promo-code')&&$('guidcy-admin-promo-code').value,type:$('guidcy-admin-promo-type')&&$('guidcy-admin-promo-type').value,value:$('guidcy-admin-promo-value')&&$('guidcy-admin-promo-value').value,maxAmount:$('guidcy-admin-promo-max')&&$('guidcy-admin-promo-max').value,startDate:$('guidcy-admin-promo-start')&&$('guidcy-admin-promo-start').value,endDate:$('guidcy-admin-promo-end')&&$('guidcy-admin-promo-end').value,active:true});
