  function bookingTimeParts(value){var raw=clean(value).replace(/\s*IST\s*$/i,''),m=raw.match(/^(\d{1,2})(?::(\d{2}))?\s*([AP]M)$/i);if(m){var h=Number(m[1])%12;if(m[3].toUpperCase()==='PM')h+=12;return {hour:h,minute:Number(m[2]||0)}}m=raw.match(/^(\d{1,2}):(\d{2})$/);if(m&&Number(m[1])<24&&Number(m[2])<60)return {hour:Number(m[1]),minute:Number(m[2])};return {hour:23,minute:59}}
