  async function authUser(){var u=currentUser(); if(u&&u.id)return u; var c=client(); if(c&&c.auth){try{return (await c.auth.getUser()).data.user}catch(_){}} return null}
  async function noteById(id){var c=client(); if(!c)throw new Error('Marketplace service is not ready.'); var r=await c.from('marketplace_notes').select('*').eq('id',id).maybeSingle(); if(r.error)throw r.error; return r.data}
