    try{await client().from('webinar_registrations').update({registration_email_sent:true,registration_email_sent_at:new Date().toISOString(),confirmation_email_sent:true,confirmation_email_sent_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',reg.id)}catch(_){}
    var host=w.publisher_email||w.host_email||w.consultant_email;
