    var data={name:clean($('wbn-reg-name')&&$('wbn-reg-name').value),email:clean($('wbn-reg-email')&&$('wbn-reg-email').value),phone:clean($('wbn-reg-phone')&&$('wbn-reg-phone').value),role:clean($('wbn-reg-role')&&$('wbn-reg-role').value),goal:clean($('wbn-reg-goal')&&$('wbn-reg-goal').value)};
    if(!data.name||!data.email||!data.phone){toast('Please fill in name, email and phone.','red');return}
