          if(!created.order||!/^order_[A-Za-z0-9]+$/.test(clean(created.order.id)))throw new Error('Payment order could not be created. Please try again.');
          var response=await openCheckout({keyId:created.keyId,order:created.order,description:'Guidcy webinar - '+(w.title||w.webinar_title||'Webinar'),prefill:{name:data.name,email:data.email,contact:data.phone},notes:{flow:'webinar',registration_id:reg.id,webinar_id:wid}});
          if(btn)btn.textContent='Verifying payment...';
          var verified=await postJSON('/api/verify-payment',Object.assign({flow:'webinar',registrationId:reg.id},response));
