    swCD:{overview:/^overview$/i,requests:/booking requests/i,schedule:/availability/i,earnings:/^earnings$/i,reviews:/client reviews/i,webinars:/webinar history/i,notifications:/^notifications$/i,settings:/settings/i,marketplace:/marketplace/i,'notification-preferences':/notification preferences/i},
    swAD:{overview:/^(analytics|overview)$/i,consultants:/manage consultants/i,users:/users/i,bookings:/bookings/i,payments:/payment/i,support:/support tickets/i,disputes:/disputes/i,'marketing-strip':/moving consultant strip/i,webinars:/webinar history/i,'promo-codes':/promo codes/i,'referral-program':/referral program/i,'marketplace-payouts':/marketplace payouts/i,'webinar-payouts':/webinar payouts/i,'consultant-earnings':/consultant earnings/i,approvals:/approval requests/i,payouts:/consultant payouts/i,featured:/featured experts/i,marketplace:/^marketplace$/i,'webinar-registrations':/webinar registrations/i}
